const artLook=a=>`background:${safe(a.bg)}`;
/* PRISM (V5) — the category hue map. Color lives in art, accents and glows,
   never in body copy. Mixed Media / All art ARE the prism gradient; their
   solid stand-ins (violet / teal) serve tints and text accents. */
const CAT_HUES={'Painting':'#FF5C8A','Digital Art':'#8B7CFF','Illustration':'#FFB84D','Photography':'#39D0C4','Sculpture':'#FF8A5C','Custom Portraits':'#FF7AD9','Pet Portraits':'#FFD166','Mixed Media':'#8B7CFF','All art':'#39D0C4'};
const PRISM_CATS=['Mixed Media','All art'];
const PRISM_GRAD='linear-gradient(90deg,#FF5C8A,#FFB84D,#AFED66,#39D0C4,#8B7CFF)';
function catHue(c){return CAT_HUES[c]||'#BDA579'}
function catBg(c){return PRISM_CATS.indexOf(c)>=0?PRISM_GRAD:(CAT_HUES[c]||'#3B3F45')}
function noImgArt(a){return '<div class="art-noimg" style="background:'+(a.bg||catBg(a.category))+'"><span class="noimg-mono">'+safe(monogram(a.artist))+'</span><span class="noimg-cat">'+safe(a.category||'Art')+'</span></div>'}
function monogram(name){return String(name||'?').trim().split(/\s+/).map(function(w){return w.charAt(0)}).slice(0,2).join('').toUpperCase()}
function avatarMono(name,style){return '<div class="artist-avatar avatar-mono"'+(style?' style="'+style+'"':'')+' aria-hidden="true">'+safe(monogram(name))+'</div>'}
/* ═══ PHASE 4 — ORIGINAL ART IDENTITY ═══
   Every listing carries an identity record: kind (original vs
   artist-authorized print), medium, dimensions, year, condition, the
   artist's own human-made attestation, shipping + returns notes.
   Rendering law: claims come only from stored fields. An attestation
   is the maker's word, recorded as given — never a platform
   verification, never a guarantee. Payment copy states exactly what
   is true today (R3): demo checkout, no escrow, no buyer protection
   promised until a dispute policy exists. */
const ID_PAY_LINE='Payment status: this prototype runs a demo checkout — no real payment is taken, and no escrow or buyer protection is promised. Real payments open at engine launch, under a published dispute policy.';
function identityOf(a){if(!a)return{recorded:false,attested:false};let kind=a.kind==='PRINT'?'PRINT':(a.kind==='ORIGINAL'?'ORIGINAL':null);let id={kind:kind,creator:a.artist||'',medium:a.medium||'',dimensions:a.dimensions||'',year:a.year||'',condition:a.condition||'',attested:!!a.attested,attest:a.attest||'',shipping:a.shipping||'',returns:a.returns||''};if(id.attest)id.attested=true;id.recorded=!!(kind||id.dimensions||id.year||id.condition||id.attest||id.shipping||id.returns);return id}
function kindLabel(kind){return kind==='PRINT'?'AUTHORIZED PRINT':'ORIGINAL · ONE OF ONE'}
function kindShort(kind){return kind==='PRINT'?'PRINT':'ORIGINAL'}
function kindChip(a){let id=identityOf(a);return id.kind?' · <span class="kind-chip" style="color:'+catHue(a.category)+'">'+kindShort(id.kind)+'</span>':''}
function idSummary(a){let id=identityOf(a);let bits=[];if(id.kind)bits.push(kindLabel(id.kind));if(id.year)bits.push(String(id.year));if(id.attested)bits.push('✦ ATTESTED');else if(id.recorded)bits.push('NOT ATTESTED');return bits.join(' · ')}
function identityPanel(a){let id=identityOf(a);let hue=catHue(a.category);let rows='';let row=function(k,v){if(v)rows+='<div class="id-row"><dt>'+k+'</dt><dd>'+safe(v)+'</dd></div>'};
row('MEDIUM',id.medium);row('DIMENSIONS',id.dimensions);row('YEAR',id.year?String(id.year):'');row('CONDITION',id.condition);row('SHIPPING',id.shipping);row('RETURNS',id.returns);
let handle=USERNAMES[id.creator];let creatorHtml=handle?'<a class="text-link" href="#/artist/'+handle+'">'+safe(id.creator)+'</a>':safe(id.creator);
let head='<div class="id-head">'+(id.kind?'<span class="id-kind" style="color:'+hue+';border-color:'+hue+'">'+kindLabel(id.kind)+'</span>':'<span class="id-kind id-kind-none">IDENTITY RECORD IN PROGRESS</span>')+'<span class="id-creator">Created by '+creatorHtml+'</span></div>';
let body=rows?'<dl class="id-rows">'+rows+'</dl>':'<p class="id-note">This listing’s identity record is not complete yet. Message the artist and ask — every PAIRED listing is on its way to carrying one.</p>';
let attest='';
if(id.attest){attest='<p class="id-attest">✦ “'+safe(id.attest)+'”</p><p class="id-attest-note">— attested by '+safe(id.creator)+', the artist, in their own words. A maker’s declaration, recorded as given: PAIRED does not independently verify pieces, and an attestation is not a platform guarantee. Ask the artist anything in the thread — that is what it is for.</p>'}
else if(id.attested){attest='<p class="id-attest">✦ “I attest that this work is human-made by me.”</p><p class="id-attest-note">— the standard declaration, given by '+safe(id.creator)+' at listing. Recorded as given: PAIRED does not independently verify pieces, and an attestation is not a platform guarantee.</p>'}
else if(id.recorded){attest='<p class="id-attest-note">No human-made attestation on record for this listing yet.</p>'}
return '<div class="identity-panel"><div class="eyebrow" style="margin-bottom:12px">Original art identity</div>'+head+body+attest+'<p class="id-pay">'+ID_PAY_LINE+'</p></div>'}
function artCard(a){let hue=catHue(a.category);let catName=PRISM_CATS.indexOf(a.category)>=0?'<span class="cat-name prism-text">'+safe(a.category)+'</span>':'<span class="cat-name" style="color:'+hue+'">'+safe(a.category)+'</span>';let media=a.img?'<img class="art-photo" src="'+safe(a.img)+'" alt="'+safe(a.title)+' by '+safe(a.artist)+'" loading="lazy">':noImgArt(a);let look=a.img?('background:'+catBg(a.category)):artLook(a);let handle=USERNAMES[a.artist]||'';return `<article class="art-card" data-pattern="split-frame" style="--card-hue:${hue}"><a href="#/art/${a.id}" aria-label="View ${safe(a.title)}"><div class="art-img" style="${look}">${media}<div class="art-overlay"></div><span class="tag">✦ ${safe(a.tag)}</span></div></a><div class="split-frame"><a class="split-artist" href="${handle?'#/artist/'+handle:'#/artists'}" aria-label="Meet ${safe(a.artist)}">${avatarMono(a.artist)}<span class="split-who"><b>${safe(a.artist)}</b><span class="split-what">${catName}${kindChip(a)}</span></span></a><div class="art-body"><h3>${safe(a.title)}</h3><div class="art-bottom"><strong class="price">${money(a.price)}</strong><div class="art-actions"><button data-action="like" data-id="${a.id}" aria-label="Save artwork">${likes().includes(a.id)?'♥':'♡'}</button><button data-action="share-piece" data-id="${a.id}" aria-label="Share artwork card">SHARE ↗</button><button data-action="add" data-id="${a.id}">ADD +</button></div></div></div></div></article>`}
