  let rec={id:'pr'+Date.now()+'-'+Math.floor(Math.random()*1e6),by:this.myKey()||'guest',kind:'fast-lane',shopUrl:url,code:code,state:'issued',legalName:'',payoutName:'',identityMatch:null,at:Date.now(),history:[{state:'issued',at:Date.now()}]};
