 let savesTotal=StudioDB.totalSavesFor(names);
 let buyersSeen={};StudioDB.load().saves.forEach(function(s){let a=StudioDB.artworkById(s.art);if(a&&a.ownerKey===k)buyersSeen[s.buyer]=1});
 ownLegacy.forEach(function(l){StudioDB.load().saves.forEach(function(s){if(String(s.art)===String(l.id))buyersSeen[s.buyer]=1})});
 let followers=StudioDB.followersOf(names);
