 let payoutTrio='<div class="studio-stats"><div class="stat" data-payout="earned"><b>'+money(earn.net)+'</b><span>EARNED — COMPLETED ACTIVITY, PREVIEW LEDGER</span></div><div class="stat" data-payout="pending"><b>'+money(earn.net)+'</b><span>PENDING PAYOUT — RELEASES AT ENGINE LAUNCH</span></div><div class="stat" data-payout="paid"><b>$0</b><span>PAID OUT — NO REAL PAYMENT HAS MOVED</span></div></div>';
 let msgRows=msgInq.length?msgInq.slice(0,6).map(function(e){return '<div class="list-row"><div class="list-info"><strong>@'+safe(e.actor||'a collector')+'</strong><small>Opened a conversation about your work'+(e.answered?' · answered':' · waiting for your answer')+'</small></div>'+(e.answered?'<a class="mini-btn" href="#/messages">OPEN THREAD</a>':'<button class="mini-btn" data-action="studio-respond">RESPOND</button>')+'</div>'}).join(''):'<div class="empty">No buyer messages yet. When a collector opens a conversation from one of your pieces, it lands here — and in Messages — the same minute.</div>';
 let completed=props.filter(function(p){return p.dir==='SENT'&&propStageOf(p)==='COMPLETE'}).length;
 let draft=StudioDB.load().drafts[k]||null;
 let receivedOpen=pr.received.filter(function(p){return propStageOf(p)==='PROPOSED'}).length;
 let move=studioNextMove({pieces:arts.length+ownLegacy.length,props:props,byStage:byStage,slots:slots,matched:matched,inquiries:inq,draft:draft,receivedOpen:receivedOpen});
 let tierName=currentArtistTier();let tier=TIER_DATA.find(function(t){return t.name===tierName})||TIER_DATA[0];
 let fnd=studioFounding(su);
 let myBriefs=get(STORE.briefs,[]).filter(function(b){return b.mine||low(b.buyer||'')===k});
 /* — My Pieces rows: sandbox artworks first, then legacy listings — */
 let pieceRows='';
 if(arts.length)pieceRows+=arts.map(studioPieceRow).join('');
 if(ownLegacy.length)pieceRows+=ownLegacy.map(function(a){return '<div class="list-row"><div class="list-thumb" style="'+artLook(a)+'">'+(a.img?'<img src="'+safe(a.img)+'" alt="">':noImgArt(a))+'</div><div class="list-info"><strong>'+safe(a.title)+'</strong><small>'+money(a.price)+' · '+safe(a.category)+' · '+safe(a.tag||'Just listed')+(idSummary(a)?' · '+safe(idSummary(a)):'')+'</small><p class="track-line">Saves '+StudioDB.saveCount(a.id)+' · Collectors interested '+StudioDB.saveBuyers(a.id)+'</p><p class="track-line">Posted to: <span class="place-chips"><span class="place-chip on">MARKETPLACE ✓</span></span> <span class="meta">· listed via the Sell page</span></p><p class="track-line">'+shippingLine(a)+'</p></div><span class="badge" style="background:#1d5c38;color:#b8ffd2">● LIVE</span><span class="row-actions"><a class="mini-btn" href="#/art/'+a.id+'">OPEN</a><button class="mini-btn" data-action="delete" data-id="'+a.id+'">DELETE</button></span></div>'}).join('');
 if(!arts.length&&!ownLegacy.length)pieceRows='<div class="empty">Your stage is empty — post your first piece and it hangs here, with every destination it travels to.<div class="actions" style="justify-content:center;margin-top:14px"><a class="primary" href="#/studio/post" style="text-decoration:none">POST YOUR FIRST PIECE →</a></div></div>';
 /* — Interest: aggregates only — */
