function ageBadge(age,big){if(age===null||age===undefined||isNaN(age))return '';let extra=big?'font-size:13px;padding:7px 13px;':'';if(age<18)return '<span class="badge" style="background:#14507a;color:#bfe3ff;'+extra+'">🛡 MINOR · 13–17</span>';return '<span class="badge" style="background:#3a3f4a;color:#e6ebf2;'+extra+'">🛡 ADULT · 18+</span>'}
const REVIEWS={'Nova Reyes':[{q:'She messaged me back within the hour and sent progress photos the whole way. The portrait made my sister cry — in the good way.',b:'Maya R.',w:'Custom portrait'},{q:'Colors are even richer in person. Packed like it was glass and gold.',b:'Dev P.',w:'Original painting'}],'Sam Rivera':[{q:'I asked for a desert piece for my studio and he asked about my light before painting. Who does that? It is perfect.',b:'Jordan T.',w:'Original painting'},{q:'Second piece I have bought from Sam. Zero drama, all heart.',b:'Priya K.',w:'Original painting'}],'River Quinn':[{q:'My commission was a weird idea and River treated it like it mattered. It did. It does.',b:'Alex M.',w:'Commission'}],'Kai Santos':[{q:'Fast, kind, and the detail up close is unreal.',b:'Sam W.',w:'Original artwork'}],'Ari Moon':[{q:'Bought a print, came back for the original. That is the review.',b:'Lee C.',w:'Print, then original'}],'Jules Carter':[{q:'Great communication from the first message to delivery day.',b:'Robin D.',w:'Original artwork'}],'Milo Banks':[{q:'Bold, strange, exactly as promised.',b:'Kit A.',w:'Original artwork'}],'Eli Morgan':[{q:'First art purchase ever. Eli made it easy and the piece is stunning.',b:'Jo F.',w:'Original artwork'}]};
function stars(r){let f=Math.round(r);return '<span class="stars" aria-label="'+r+' out of 5 stars">'+'★'.repeat(f)+'☆'.repeat(5-f)+'</span>'}
function topSellers(){let names=[...new Set(all().map(a=>a.artist))].filter(n=>RATINGS[n]);names.sort((a,b)=>RATINGS[b].r-RATINGS[a].r||RATINGS[b].n-RATINGS[a].n);let rtitles=['World Serpent','Titanoboa','King Cobra'];let rcolors=['#FFC94D','#D7DCE6','#E39A5F'];let podium=names.slice(0,3).map((n,i)=>{let t=RATINGS[n];let rv=(REVIEWS[n]||[])[0];return '<div class="panel" style="text-align:center;padding:26px 20px"><div class="medal-num" style="border-color:'+rcolors[i]+';color:'+rcolors[i]+'">#'+(i+1)+'</div><div style="font-family:Syne,sans-serif;font-size:21px;letter-spacing:1px;color:'+rcolors[i]+';margin-top:6px">#'+(i+1)+' '+rtitles[i]+'</div>'+avatarMono(n,'margin:10px auto')+'<h3 style="font-size:22px">'+safe(n)+'</h3><div style="margin-top:6px">'+ageBadge(AGES[n])+'</div><div style="margin:6px 0">'+stars(t.r)+' <b style="color:#fff">'+t.r+'</b></div><p class="meta">'+t.n+' customer reviews</p>'+(rv?'<p style="line-height:1.65;font-style:italic;margin-top:12px">“'+safe(rv.q)+'”</p><p class="meta">— '+safe(rv.b)+' · '+safe(rv.w)+'</p>':'')+'<div class="actions" style="justify-content:center"><button class="outline" data-action="contact" data-artist="'+safe(n)+'">MESSAGE ARTIST ✉</button></div></div>'}).join('');let rows=names.slice(3).map((n,i)=>{let t=RATINGS[n];let rv=(REVIEWS[n]||[])[0];return '<div class="panel" style="display:flex;gap:16px;align-items:flex-start;margin-bottom:12px"><div style="font-size:22px;font-weight:900;color:#fff;min-width:34px">#'+(i+4)+'</div><div style="flex:1"><h3>'+safe(n)+' '+ageBadge(AGES[n])+'</h3><div style="margin:4px 0">'+stars(t.r)+' <b style="color:#fff">'+t.r+'</b> <span class="meta">· '+t.n+' reviews</span></div>'+(rv?'<p style="line-height:1.6;font-style:italic">“'+safe(rv.q)+'”</p><p class="meta">— '+safe(rv.b)+' · '+safe(rv.w)+'</p>':'')+'</div><button class="outline" data-action="contact" data-artist="'+safe(n)+'">MESSAGE ✉</button></div>'}).join('');return '<div class="page-hero" style="--ph:#FFD166"><div class="shell" style="display:flex;gap:26px;align-items:center;flex-wrap:wrap"><div style="flex:1;min-width:270px"><div class="eyebrow">Rated by the people who bought the art</div><h1 class="page-title">TOP <span class="paint">SELLERS.</span></h1><p class="sub">The highest-rated artists on PAIRED, ranked by the customers who actually bought from them. Every rating comes from a completed order — no bought stars, no fake love. The top three hold serpent titles — World Serpent, Titanoboa, King Cobra — earned, never given.</p></div><img class="hero-mark" src="assets/paired-mark.svg" alt="The PAIRED interlock mark"></div></div><section class="section" style="padding-top:26px"><div class="shell"><div class="art-grid" style="margin-bottom:26px">'+podium+'</div>'+rows+'<div class="panel" style="margin-top:22px"><h3>How ratings work</h3><div class="steps" style="margin-top:12px"><div class="step"><b>1</b><h4>Order completes</h4><p>Only customers whose order was delivered can rate the artist — 1 to 5 stars, plus a written review.</p></div><div class="step"><b>2</b><h4>Reviews stay honest</h4><p>Reviews live on the artist’s record permanently. Artists can reply, but never edit or delete what a customer said.</p></div><div class="step"><b>3</b><h4>The board ranks itself</h4><p>Top Sellers sorts by average rating, with review count breaking ties. Care for your customers and the board notices.</p></div></div><p class="meta" style="margin-top:14px">Preview board: ratings and reviews go live with real orders at launch — the artists and reviews shown here demonstrate exactly how the board will look and work.</p></div></div></section>'}

