function briefPitches(b){if(b.mine)return b.pitches||0;return (b.pitches||0)+(get(STORE.pitchbonus,{})[b.id]||0)}
function allBriefs(){return [...get(STORE.briefs,[]),...BRIEF_SEED]}
function openThread(name){let box=get(STORE.messages,{});if(!box[name]){box[name]=[];set(STORE.messages,box)}state.chatTo=name}
function pitchBrief(bid,buyer){let bonus=get(STORE.pitchbonus,{});bonus[bid]=(bonus[bid]||0)+1;set(STORE.pitchbonus,bonus);state.propBriefId=bid;state.propDraft=null;let pb=allBriefs().find(b=>String(b.id)===String(bid));if(pb&&pb.mine)addAlert('pitch','✦ A pitch landed on your brief “'+pb.title+'” — the thread waits in your Messages.','#/messages');openThread(buyer)}
const TIER_FEES=Object.fromEntries(TIER_DATA.map(t=>[t.name,t.fee]));
const FEE_LABEL='after platform fee · processing shown at checkout';
function currentArtistTier(){let su=get(STORE.signup,{});return (su&&TIER_FEES[su.tier]!=null)?su.tier:'Solo'}
function proposalMath(items,offered,selected,mult,tier){let base=(items||[]).reduce((s,i)=>s+(Number(i.price)||0),0);let sel=selected||{};let off=offered||{};let m=Number(mult)||2;let rush=(off.rush&&sel.rush)?base:0;let privacy=(off.privacy&&sel.privacy)?Math.round(base*50)/100:0;let commercial=(off.commercial&&sel.commercial)?Math.round(base*(m-1)*100)/100:0;let total=Math.round((base+rush+privacy+commercial)*100)/100;let rate=TIER_FEES[tier]!=null?TIER_FEES[tier]:8;let fee=Math.round(total*rate)/100;let keep=Math.round((total-fee)*100)/100;return{base:base,rush:rush,privacy:privacy,commercial:commercial,total:total,rate:rate,fee:fee,keep:keep,mult:m}}
function getProposals(contact){let allP=get(STORE.proposals,{});return allP[contact]||[]}
function latestProposal(contact){let l=getProposals(contact);return l.length?l[l.length-1]:null}
function saveProposal(p){let allP=get(STORE.proposals,{});let l=allP[p.contact]||[];let ix=l.findIndex(x=>x.id===p.id);if(ix>=0)l[ix]=p;else l.push(p);allP[p.contact]=l;set(STORE.proposals,allP)}
function allProposalsFlat(){let allP=get(STORE.proposals,{});let out=[];Object.keys(allP).forEach(k=>{(allP[k]||[]).forEach(p=>out.push(p))});return out}
const STAGES=['PROPOSED','ACCEPTED','IN PROGRESS','DELIVERED','COMPLETE'];
function stageRail(p){if(!p)return '';if(p.status==='DECLINED')return '<div class="stage-rail"><span class="stage closed">✕ DECLINED — COMMISSION CLOSED</span></div>';let cur=p.status==='COUNTERED'?'PROPOSED':p.stage;let ix=STAGES.indexOf(cur);return '<div class="stage-rail" aria-label="Commission stage">'+STAGES.map((s,i)=>'<span class="stage '+(i<ix?'done':i===ix?'now':'')+'">'+(i<ix?'✓ ':'')+s+'</span>'+(i<STAGES.length-1?'<span class="stage-arrow">→</span>':'')).join('')+'</div>'}
const SLOT_SEED={'Nova Reyes':{total:4,used:2},'Sam Rivera':{total:5,used:4},'River Quinn':{total:3,used:1},'Kai Santos':{total:4,used:3},'Ari Moon':{total:4,used:1},'Jules Carter':{total:3,used:2},'Milo Banks':{total:5,used:2},'Eli Morgan':{total:3,used:0}};
function slotsFor(name){let seed=SLOT_SEED[name];if(!seed)return null;let accepted=allProposalsFlat().filter(p=>p.artist===name&&['ACCEPTED','IN PROGRESS','DELIVERED','COMPLETE'].indexOf(p.stage)>=0).length;let used=Math.min(seed.total,seed.used+accepted);return{total:seed.total,used:used,open:seed.total-used}}
function slotsChip(name){let s=slotsFor(name);if(!s)return '';if(s.open>0)return '<span class="chip slots-chip">✦ '+s.open+' of '+s.total+' commission slots open</span>';return '<span class="chip slots-chip full">✦ Queue full — waitlist open</span>'}
function propDraft(){if(!state.propDraft)state.propDraft={labels:['',''],prices:['',''],days:14,revisions:2,revNote:'',briefId:state.propBriefId||'',rush:false,privacy:false,commercial:false,mult:'2.5',artist:''};if(state.propBriefId&&!state.propDraft.briefId)state.propDraft.briefId=state.propBriefId;return state.propDraft}
function harvestPropDraft(){let d=propDraft();let labels=document.querySelectorAll('[data-prop-label]');if(labels&&labels.length){d.labels=[];d.prices=[];labels.forEach(function(el){d.labels.push(el.value||'')});document.querySelectorAll('[data-prop-price]').forEach(function(el){d.prices.push(el.value||'')})}let g=function(id){let el=document.getElementById(id);return el?el.value:null};let v;if((v=g('pArtist'))!==null&&v!==undefined)d.artist=v;if((v=g('pBrief'))!==null&&v!==undefined)d.briefId=v;if((v=g('pDays'))!==null&&v!==undefined)d.days=v;if((v=g('pRevisions'))!==null&&v!==undefined)d.revisions=v;if((v=g('pRevNote'))!==null&&v!==undefined)d.revNote=v;if((v=g('pMult'))!==null&&v!==undefined)d.mult=v;let c=function(id){let el=document.getElementById(id);return el?!!el.checked:null};let cv;if((cv=c('pRush'))!==null)d.rush=cv;if((cv=c('pPrivacy'))!==null)d.privacy=cv;if((cv=c('pCommercial'))!==null)d.commercial=cv;return d}
function proposalCard(p){if(!p)return '';let m=proposalMath(p.items,p.offered,p.selected,p.mult,p.tier);let locked=['ACCEPTED','IN PROGRESS','DELIVERED','COMPLETE'].indexOf(p.stage)>=0;let closed=p.status==='DECLINED';let addonRow=function(kind,label,amt,note){if(!p.offered[kind])return '';let on=!!p.selected[kind];return '<div class="prop-addon"><div><b>'+label+'</b> <span class="meta">'+note+'</span></div><div class="prop-addon-r"><b>'+(amt?money(amt):'—')+'</b>'+(locked||closed?'':'<button class="mini-btn" data-action="prop-addon" data-kind="'+kind+'" data-id="'+p.id+'">'+(on?'✓ ADDED':'ADD +')+'</button>')+'</div></div>'};let advance='';if(p.stage==='ACCEPTED')advance='<button class="primary" data-action="prop-advance" data-id="'+p.id+'">START WORK →</button>';else if(p.stage==='IN PROGRESS')advance='<button class="primary" data-action="prop-advance" data-id="'+p.id+'">MARK DELIVERED →</button>';else if(p.stage==='DELIVERED')advance='<button class="primary" data-action="prop-advance" data-id="'+p.id+'">CONFIRM COMPLETE ✓</button>';else if(p.stage==='COMPLETE')advance='<span class="meta">✓ Commission complete — delivered and confirmed (demo).</span>';return '<div class="proposal-card"><div class="prop-head"><b>✦ COMMISSION PROPOSAL</b><span class="badge '+(closed?'prop-closed-badge':'')+'">'+safe(p.status)+'</span></div>'+stageRail(p)+'<p class="meta" style="margin:8px 0">For: <b style="color:#fff">'+safe(p.briefTitle)+'</b> · Artist: <b style="color:#fff">'+safe(p.artist)+'</b> · Demo proposal — no payment moves here.</p><div class="prop-items">'+p.items.map(i=>'<div class="prop-item"><span>'+safe(i.label)+'</span><b>'+money(i.price)+'</b></div>').join('')+'<div class="prop-item subtotal"><span>Base</span><b>'+money(m.base)+'</b></div></div>'+addonRow('rush','✦ RUSH',m.rush,'+100% of base — jumps the queue')+addonRow('privacy','✦ PRIVACY',m.privacy,'+50% of base — never posted publicly')+addonRow('commercial','✦ COMMERCIAL USE',m.commercial,'×'+m.mult+' of base (license uplift shown)')+'<div class="prop-total"><span>TOTAL</span><b>'+money(m.total)+'</b></div><p class="prop-fee">Platform fee '+m.rate+'% ('+safe(p.tier)+'): '+money(m.fee)+' — artist keeps '+money(m.keep)+' '+FEE_LABEL+'</p><p class="meta">◷ Delivery estimate: '+p.days+' days · ✦ Revisions: '+p.revisions+' round'+(Number(p.revisions)===1?'':'s')+(p.revNote?' — '+safe(p.revNote):'')+'</p>'+(closed?'<p class="meta">This proposal was declined — the thread stays open for a kinder idea.</p>':locked?'<div class="actions" style="margin-top:10px">'+advance+'</div>':'<div class="actions" style="margin-top:10px"><button class="primary" data-action="prop-accept" data-id="'+p.id+'">ACCEPT ✓</button><button class="outline" data-action="prop-counter" data-id="'+p.id+'">COUNTER — REPLY IN THREAD</button><button class="outline" data-action="prop-decline" data-id="'+p.id+'">DECLINE</button></div>')+'</div>'}
function proposalBuilder(hasProp){let d=propDraft();let briefs=allBriefs();let artistDefault=d.artist||(USERNAMES[state.chatTo]?state.chatTo:(get(STORE.signup,{}).username||''));let rows=d.labels.map((l,i)=>'<div class="form-group"><label>LINE ITEM '+(i+1)+'</label><input class="field" data-prop-label value="'+safe(l)+'" placeholder="e.g. Full-body character, colored" maxlength="90"></div><div class="form-group"><label>PRICE (USD)</label><input class="field" data-prop-price type="number" min="1" max="100000" step="0.01" value="'+safe(d.prices[i]||'')+'" placeholder="150"></div>').join('');let form='<form id="proposalForm" class="form-grid"><div class="form-group"><label for="pArtist">ARTIST NAME</label><input id="pArtist" class="field" value="'+safe(artistDefault)+'" maxlength="70" placeholder="The artist making this offer"></div><div class="form-group"><label for="pBrief">FOR WHICH BRIEF?</label><select id="pBrief" class="field"><option value="">Custom commission (no brief)</option>'+briefs.map(b=>'<option value="'+safe(b.id)+'"'+(String(b.id)===String(d.briefId)?' selected':'')+'>'+safe(b.title)+'</option>').join('')+'</select></div>'+rows+'<div class="full actions" style="margin:0"><button type="button" class="mini-btn" data-action="prop-add-row">+ ADD LINE ITEM</button>'+(d.labels.length>1?'<button type="button" class="mini-btn" data-action="prop-remove-row">− REMOVE LAST ITEM</button>':'')+'</div><div class="form-group"><label for="pDays">DELIVERY ESTIMATE (DAYS)</label><input id="pDays" class="field" type="number" min="1" max="365" value="'+safe(d.days)+'"></div><div class="form-group"><label for="pRevisions">REVISION ROUNDS INCLUDED</label><input id="pRevisions" class="field" type="number" min="0" max="20" value="'+safe(d.revisions)+'"></div><div class="form-group full"><label for="pRevNote">WHAT COUNTS AS A REVISION?</label><input id="pRevNote" class="field" value="'+safe(d.revNote)+'" maxlength="200" placeholder="e.g. Pose and palette changes count; a new character is a new item"></div><div class="form-group full"><label>STANDARD ADD-ONS TO OFFER</label><div class="prop-offers"><label><input type="checkbox" id="pRush"'+(d.rush?' checked':'')+'> ✦ Rush (+100% of base)</label><label><input type="checkbox" id="pPrivacy"'+(d.privacy?' checked':'')+'> ✦ Privacy (+50% of base)</label><label><input type="checkbox" id="pCommercial"'+(d.commercial?' checked':'')+'> ✦ Commercial use (×2–3 of base)</label></div></div><div class="form-group"><label for="pMult">COMMERCIAL MULTIPLIER</label><select id="pMult" class="field"><option'+(String(d.mult)==='2'?' selected':'')+'>2</option><option'+(String(d.mult)==='2.5'?' selected':'')+'>2.5</option><option'+(String(d.mult)==='3'?' selected':'')+'>3</option></select></div><div class="form-group"><label>YOUR TIER (FEE SHOWN BEFORE ACCEPTANCE)</label><p class="form-note" style="margin:0">'+safe(currentArtistTier())+' — '+TIER_FEES[currentArtistTier()]+'% platform fee. The buyer sees the fee and what you keep before anyone accepts.</p></div><div class="full"><button class="primary" type="submit">SEND PROPOSAL ✦</button><p id="propMsg" style="margin-top:10px;line-height:1.6" role="alert"></p><p class="form-note">Demo builder — proposals live in this browser only. Proposal text passes the same safety screen as bios.</p></div></form>';if(hasProp)return '<details class="prop-builder"><summary>✦ BUILD ANOTHER PROPOSAL</summary>'+form+'</details>';return '<div class="prop-builder open"><h3 style="margin:0 0 4px">✦ BUILD A PROPOSAL</h3><p class="meta" style="margin-bottom:14px">Itemized, honest, in-thread — the pitch becomes a real offer.</p>'+form+'</div>'}
function briefCard(b,inWorld){let n=briefPitches(b);let sm=strongMatches(b);let matchRow=sm.length?'<div class="match-row"><span class="match-k">✦ STRONG MATCH — ARTISTS IN '+safe(b.category).toUpperCase()+'</span><div class="match-list">'+sm.map(function(nm){return '<span class="match-chip"><span class="match-mono">'+safe(monogram(nm))+'</span><b>'+safe(nm)+'</b><button class="mini-btn" data-action="contact" data-artist="'+safe(nm)+'">MESSAGE ✉</button></span>'}).join('')+'</div></div>':'';return `<article class="panel brief-card"><div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"><span class="chip">✦ ${safe(b.category)}</span>${b.mine?'<span class="badge" style="background:#1d5c38;color:#b8ffd2">✦ YOUR BRIEF</span>':'<span class="badge">EXAMPLE BRIEF</span>'}${inWorld?'<span class="badge world-badge">✦ MATCHES YOUR CATEGORIES</span>':''}${b.type==='surprise'?'<span class="badge surprise-badge">✦ SURPRISE ME · FIXED · NO REVISIONS</span>':''}</div><h3>${safe(b.title)}</h3><div class="brief-meta"><span class="chip">${briefBudgetLine(b)}</span><span class="chip">◷ ${safe(b.timeline)}</span>${b.size?'<span class="chip">▣ Size: '+safe(b.size)+'</span>':''}${b.deadline?'<span class="chip">Needed by '+safe(b.deadline)+'</span>':''}${b.type==='surprise'?'<span class="chip">✦ Artist has creative freedom</span>':''}</div><p class="brief-details">${safe(b.details)}</p>${matchRow}<div class="brief-foot"><div class="brief-buyer"><div class="brief-avatar">${safe((b.buyer||'C').charAt(0))}</div><div><b style="color:#fff">${safe(b.buyer)}</b><p class="meta">Collector · ${n} pitch${n===1?'':'es'} so far</p></div></div>${b.mine?'<span class="meta">Pitches land in your Messages</span>':`<button class="outline" data-action="pitch" data-artist="${safe(b.buyer)}" data-brief="${safe(b.id)}">PITCH ✉</button>`}</div></article>`}
function board(){let cat=state.boardCategory||'All categories';let briefs=allBriefs().filter(b=>cat==='All categories'||b.category===cat);let acct=get(STORE.signup,{});let poster=acct.username?acct.username:'Guest collector';let cards=briefs.map(b=>briefCard(b)).join('');return `<div class="page-hero grotto-hero"><div class="shell"><div class="eyebrow">The Commission Board</div><h1 class="page-title">ASK FOR THE <span class="paint">IMPOSSIBLE.</span></h1><p class="sub">Dreaming of a piece that does not exist yet? Post the brief. Artists read the wall, pick the dreams they love, and pitch you right here — the conversation becomes the commission.</p><div class="actions"><button class="primary" data-action="scrollto" data-target="post-brief">POST A BRIEF ↗</button><a class="outline" href="#/artists" style="text-decoration:none;display:inline-flex;align-items:center">MEET THE ARTISTS →</a></div></div></div><section class="section"><div class="shell"><div class="section-top"><div><div class="eyebrow">Open briefs</div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">THE <span class="paint">WALL.</span></h2></div><p class="meta" style="max-width:340px">Example briefs show how the board works — real collector briefs open with the Founding 100 at launch. Briefs you post appear here on this browser.</p></div><div class="pills">${['All categories',...CATEGORIES].map(c=>`<button class="pill ${c===cat?'active':''}" data-action="board-cat" data-cat="${safe(c)}" style="--pill-hue:${catHue(c)}"${c===cat&&PRISM_CATS.indexOf(c)>=0?' data-prism="1"':''}>${safe(c)}</button>`).join('')}</div>${yourBoardStrip()}${briefs.length?`<div class="brief-grid">${cards}</div>`:'<div class="empty">No briefs in this category yet. Yours could be the first — post it below.</div>'}</div></section><section class="section alt" id="post-brief"><div class="shell two-col"><div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">POST A <span class="paint">BRIEF.</span></h2><p class="sub" style="margin-bottom:16px">Tell the wall what you are dreaming of. Keep contact details out of the brief — conversations stay here, where they are protected.</p><div class="panel"><form id="briefForm" class="form-grid"><div class="form-group full"><label for="bfTitle">SUBJECT — WHAT DO YOU WANT MADE? *</label><input id="bfTitle" class="field" name="title" placeholder="e.g. A portrait of my grandmother's garden — or an emote pack for your stream" required maxlength="110"></div><div class="form-group full"><label>BRIEF TYPE *</label><div class="brief-types"><label class="type-card"><input type="radio" name="briefType" value="standard" checked> <b>STANDARD</b><span>Full brief — details, timeline, revisions agreed in the thread.</span></label><label class="type-card"><input type="radio" name="briefType" value="surprise"> <b>SURPRISE ME</b><span>Fixed price · no revisions · the artist has creative freedom (Skeb-style).</span></label></div></div><div class="form-group full"><label>GAMING-NATIVE? START FROM A SHAPE</label><div class="pills" style="margin:0">${['Emote pack','Stream overlay','Avatar / VTuber art','OC / character'].map(g=>`<button type="button" class="pill" data-action="brief-idea" data-idea="${g}">${g}</button>`).join('')}</div><p class="form-note">Tap a shape to pre-fill your brief — emote packs, stream overlays, avatar / VTuber art and OC / character commissions are royalty here.</p></div><div class="form-group"><label for="bfCategory">CATEGORY *</label><select id="bfCategory" class="field" name="category">${CATEGORIES.map(c=>`<option>${c}</option>`).join('')}</select></div><div class="form-group"><label for="bfBand">BUDGET BAND *</label><select id="bfBand" class="field" name="budgetBand">${BUDGET_BANDS.map(function(b){return '<option value="'+b.label+'">'+b.label+'</option>'}).join('')}</select></div><div class="form-group"><label for="bfSize">SIZE IN MIND *</label><input id="bfSize" class="field" name="size" placeholder="e.g. 24 × 36 in — or 'a hallway wall'" required maxlength="60"></div><div class="form-group"><label for="bfTimeline">TIMELINE *</label><select id="bfTimeline" class="field" name="timeline"><option>This week</option><option>Within a month</option><option>1–3 months</option><option>No rush — when it is right</option></select></div><div class="form-group"><label for="bfDeadline">DEADLINE DATE (OPTIONAL)</label><input id="bfDeadline" class="field" name="deadline" type="date"></div><div class="form-group full"><label for="bfDetails">THE DETAILS *</label><textarea id="bfDetails" class="field" name="details" placeholder="Size, colors, the story behind it — anything that helps an artist picture your piece." required maxlength="700"></textarea></div><div class="full"><button class="primary" type="submit">POST MY BRIEF ✦</button><p id="briefMsg" style="margin-top:10px;line-height:1.6" role="alert"></p><p class="form-note">Posting as <b style="color:#fff">${safe(poster)}</b>${acct.username?'':' — sign up on the Sell page to post under your own name'}. Your brief passes the same safety check as every bio: no contact info, no rough language.</p></div></form></div></div><aside><div class="steps" style="display:block"><div class="step"><span class="number">01</span><h3>POST THE DREAM</h3><p>Name the piece, the budget, and the moment it is for. Honest briefs get honest pitches.</p></div><div class="step" style="margin-top:14px"><span class="number">02</span><h3>ARTISTS PITCH YOU</h3><p>Artists who love your brief open a thread with their idea, their price, and their timeline.</p></div><div class="step" style="margin-top:14px"><span class="number">03</span><h3>TALK. AGREE. COMMISSION.</h3><p>The thread holds the whole story — idea, agreement, progress, delivery. The conversation is the commission.</p></div></div></aside></div></section>`}
function login(){let known=get(STORE.known,null);let active=get(STORE.signup,{});let acctList=accountRows(active.username||'');return `<div class="page-hero" style="--ph:#8B7CFF"><div class="shell"><div class="eyebrow">Welcome back</div><h1 class="page-title">STEP BACK <span class="paint">IN.</span></h1><p class="sub">Your stage is right where you left it.</p></div></div><section class="section"><div class="shell"><div class="panel" style="max-width:560px;margin:auto"><h2 class="section-title" style="font-size:30px">LOG <span class="paint">IN.</span></h2><p class="sub" style="margin:10px 0 16px">${known?`An account lives on this device: <b style="color:#fff">@${safe(known.username||'')}</b> — type your email and username to step back in.`:`Type the email and username you signed up with, and step back in.`}</p>${acctList}<form id="loginForm" class="form-grid"><div class="form-group full"><label for="liEmail">EMAIL ADDRESS *</label><input id="liEmail" class="field" name="email" type="email" placeholder="you@example.com" required></div><div class="form-group full"><label for="liUsername">USERNAME *</label><input id="liUsername" class="field" name="username" placeholder="your.username" required></div><div class="full"><button class="primary" type="submit" style="width:100%">LOG IN ✦</button><p id="loginMsg" style="margin-top:10px;line-height:1.6" role="alert"></p><p class="form-note">New to PAIRED? <a class="text-link" href="#/sell">Create your account</a> — it takes about a minute.</p><p class="form-note" style="margin-top:8px">✦ Founding preview — PAIRED is in founding preview, and full accounts open at launch. Until then, this door opens the house exactly as it stands: honestly, and early.</p></div></form></div></div></section>`}
function signInGate(room){let conf={account:{ph:'#8B7CFF',eyebrow:'Your account',title:'YOUR <span class="paint">STAGE.</span>',body:'An account is personal: it holds YOUR profile, YOUR orders, YOUR membership. Sign in and the room is already yours — nobody else stands in for it. On this device, an account begins the moment you list your first piece or join as an artist.'},saved:{ph:'#FF5C8A',eyebrow:'Your collection',title:'YOUR SAVED <span class="paint">PIECES.</span>',body:'Saved pieces live with your account, so this room opens when you sign in. Everything you save waits for you here — nothing is lost, nothing is promised early.'},orders:{ph:'#39D0C4',eyebrow:'PAIRED Sound · orders',title:'YOUR SOUND <span class="paint">ORDERS.</span>',body:'Orders are personal — totals, licenses, delivery milestones. Sign in and your Sound orders are here, exactly as you left them.'}}[room]||{ph:'#8B7CFF',eyebrow:'Members',title:'YOUR <span class="paint">ROOM.</span>',body:'This room opens when you sign in.'};return `<div class="page-hero" style="--ph:${conf.ph}"><div class="shell"><div class="eyebrow">✦ ${conf.eyebrow}</div><h1 class="page-title">${conf.title}</h1></div></div><section class="section fill"><div class="shell"><div class="panel studio-door"><div class="eyebrow">Members only</div><h2 style="font-size:28px;margin:8px 0">THIS ROOM OPENS WHEN YOU SIGN IN.</h2><p class="sub" style="margin-bottom:16px">${conf.body}</p><div class="actions"><a class="primary" href="#/login" style="text-decoration:none">LOG IN ✦</a><button class="outline" data-action="join-role" data-role="artist">CREATE ACCOUNT — I'M AN ARTIST →</button><button class="outline" data-action="join-role" data-role="collector">I'M A COLLECTOR →</button></div></div></div></section>`}
function savedPage(){let su=get(STORE.signup,null);if(!su||!su.username)return signInGate('saved');state.category='All art';return explore(true)}
function guardInner(name){return `<div class="eyebrow" style="color:#FFB03A">🛡 Safeguard — minor artist</div><h3 style="margin:6px 0 8px">Direct messaging with ${safe(name)} is disabled on PAIRED.</h3><p class="sub" style="line-height:1.7">Artists under 18 cannot be contacted directly here — no exceptions, no workarounds. A commission involving a minor artist goes through a parent or guardian and the PAIRED desk, never person-to-person.</p><p class="sub" style="line-height:1.7;margin-top:8px">Safeguarding questions or concerns: bring them to the PAIRED desk via <a class="text-link" href="#/common">The Common Room</a> and mark them SAFEGUARDING — a human reviews every one.</p>`}
function guardPanel(name){return `<div class="panel" style="margin:19px">${guardInner(name)}</div>`}
function guardModal(){return `<div class="guard-overlay"><div class="guard-card">${guardInner(state.guardFor)}<div class="actions" style="margin-top:16px"><button class="primary" data-action="guard-close">UNDERSTOOD ✦</button></div></div></div>`}
function emptyState(savedOnly){if(savedOnly)return `<div class="empty">Nothing saved here yet. Tap the heart on any piece and it waits for you in this room.</div>`;if(state.query)return `<div class="empty">Nothing on the wall matches that search yet. Try another word — or put it on the request list below.</div>`+requestBlock();return requestBlock()}
function requestBlock(){return `<div class="empty conv-block"><h3 style="font-family:'Fraunces',serif;font-size:26px;margin-bottom:8px">Original artwork is coming to this category.</h3><p class="sub" style="max-width:560px;margin:0 auto 16px">We're recruiting independent artists working in this medium. This wall stays honest until they hang their first pieces — nothing padded, nothing borrowed, nothing faked.</p><div class="actions" style="justify-content:center"><a class="primary" href="#/founding100" style="text-decoration:none">JOIN AS AN ARTIST →</a><button class="outline" data-action="request-art">REQUEST THIS KIND OF ART →</button></div></div>`}
function requestArt(){let cat=state.requestCat&&CATEGORIES.indexOf(state.requestCat)>=0?state.requestCat:(state.category&&state.category!=='All art'?state.category:'');let mine=get(STORE.requests,[]);return `<div class="page-hero" style="--ph:#FFB03A"><div class="shell"><div class="eyebrow">✦ The request list</div><h1 class="page-title">REQUEST THIS KIND <span class="paint">OF ART.</span></h1><p class="sub">Tell the wall what you're dreaming of. When artists working in this medium join PAIRED, real requests are the first thing we show them.</p></div></div><section class="section"><div class="shell" style="max-width:840px"><div class="notice" style="margin-bottom:18px">This is the REQUEST LIST — an interest list, not a live commission. No artist is assigned, no payment is taken, and nothing is booked. It exists so demand is visible before supply arrives: your request helps recruit the artist who can make it.</div>${mine.length?'<p style="margin-bottom:14px"><span class="badge" style="background:#123f2a;color:#b8ffd2">✦ YOU ARE ON THE REQUEST LIST — ON THIS DEVICE ('+mine.length+')</span></p>':''}<form id="requestForm" class="form-grid panel" style="padding:26px"><div class="form-group"><label for="rqName">YOUR NAME *</label><input id="rqName" class="field" name="name" placeholder="Your name" required maxlength="70"></div><div class="form-group"><label for="rqEmail">EMAIL ADDRESS *</label><input id="rqEmail" class="field" name="email" type="email" placeholder="you@example.com" required maxlength="120"></div><div class="form-group"><label for="rqCategory">KIND OF ART *</label><select id="rqCategory" class="field" name="category">${CATEGORIES.concat(['Something else entirely']).map(c=>`<option${c===cat?' selected':''}>${c}</option>`).join('')}</select></div><div class="form-group"><label for="rqBudget">BUDGET IN MIND (OPTIONAL)</label><input id="rqBudget" class="field" name="budget" placeholder="e.g. around $400"></div><div class="form-group full"><label for="rqDetails">THE PIECE YOU'RE DREAMING OF *</label><textarea id="rqDetails" name="details" placeholder="Subject, size, colors, the room it lives in — anything that helps an artist picture it." required maxlength="900"></textarea></div><div class="full"><button class="primary" type="submit">PUT ME ON THE REQUEST LIST ✦</button><p id="requestMsg" style="margin-top:10px;line-height:1.6" role="alert"></p><p class="form-note">Stored only in this browser in the prototype (slither-requests-v1) and never sent anywhere. One list, one purpose: matching real requests to real artists at launch.</p></div></form></div></section>`}
function submitRequest(d){let name=String(d.name||'').trim(),email=String(d.email||'').trim(),details=String(d.details||'').trim();if(name.length<2)return{ok:false,msg:'Tell us your name — the request list is a list of people, not addresses.'};if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email))return{ok:false,msg:'That email does not look complete — it is how the list reaches you at launch.'};if(details.length<8)return{ok:false,msg:'Give the artist a little more to picture — a sentence or two about the piece.'};let bc=bioCheck(name+' '+details);if(!bc.ok)return{ok:false,msg:bc.why==='contact'?'🛡 Contact details can’t ride in the text fields — your email stays private inside the list itself.':'🛡 Our safety check flagged words in your entry, so it has not been stored. Try a kinder wording.'};let list=get(STORE.requests,[]),ne=email.toLowerCase();if(list.some(a=>String(a.email||'').toLowerCase()===ne))return{ok:false,msg:'This email is already on the request list on this device — one entry per person, and yours is already here.'};let rec={id:Date.now(),name:name,email:email,category:String(d.category||''),budget:String(d.budget||''),details:details,at:Date.now()};set(STORE.requests,[rec,...list]);addAlert('request','✦ Art request recorded for '+name+' ('+rec.category+') — the request list, stored on this device, in this prototype.','#/request');return{ok:true,rec:rec}}
function account(){let acct=get(STORE.signup,null);if(!acct||!acct.username)return signInGate('account');let example=!acct;let name=example?'Nova Reyes':(acct.username||'Your Studio');let handle=example?'@novareyes':(acct.username?'@'+acct.username:'');let email=example?'nova@novareyes.art':acct.email;let mine=example?all().filter(a=>a.artist==='Nova Reyes'):get(STORE.listings,[]);let rating=example?RATINGS['Nova Reyes']:null;let pr=example?'She/Her':(acct.pronouns||'');let others=example?[]:getAccounts().filter(function(x){return low(x.username)!==low(acct.username)});let curRole=example?null:PairedAuth.role();
 let rolePanelHtml=example?'':'<div class="panel" style="margin-top:16px"><h3>Your role — your home dashboard</h3><p class="sub" style="margin:8px 0 4px;font-size:13px">Role picks which dashboard opens first and which door the sections feed. It is routing, not a rank: one account, both doors, always.</p>'+(curRole?'<p style="line-height:1.8">You are here as '+(curRole==='artist'?'an':'a')+' <b style="color:#fff">'+(curRole==='artist'?'ARTIST':'COLLECTOR')+'</b>.</p>':'<p style="line-height:1.8"><b style="color:#FFB03A">No role chosen yet</b> — pick one and your home dashboard locks in.</p>')+'<div class="actions" style="margin-top:10px;flex-wrap:wrap"><button class="small-btn" data-action="set-role" data-role="artist">ARTIST — STUDIO FIRST</button><button class="small-btn" data-action="set-role" data-role="collector">COLLECTOR — COLLECTION FIRST</button></div><p class="form-note" style="margin-top:10px">Switching changes only your front door: your listings, saves, orders and records stay exactly where they are. Account system: '+PairedAuth.providerLabel()+' — production sign-in (Clerk) arrives with the engine, and this device record carries over.</p></div>';
 let switchHtml=(!example&&others.length)?'<div class="panel" style="margin-top:16px"><h3>Switch account</h3><p class="sub" style="margin:8px 0 4px;font-size:13px">More than one artist on this device? Jump between studios in one tap.</p>'+others.map(function(r){return '<div style="display:flex;gap:10px;align-items:center;padding:9px 0;border-top:1px solid #3B3F45"><div style="flex:1"><b style="color:#fff">'+safe(r.username)+'</b><p class="meta" style="color:var(--cyan)">@'+safe(low(r.username))+'</p></div><button class="small-btn" data-action="login-as" data-u="'+safe(r.username)+'">SWITCH</button></div>'}).join('')+'</div>':'';let photos=(mine.length?mine:all()).slice(0,6);let feed=mine.length?mine:all().slice(0,2);let posts=feed.map(a=>'<div class="panel" style="margin-bottom:16px"><div style="display:flex;gap:10px;align-items:center;margin-bottom:12px"><div class="artist-avatar avatar-mono" style="width:42px;height:42px;font-size:20px;overflow:hidden">'+avatarInner(example,name)+'</div><div><b style="color:#fff">'+safe(name)+'</b><p class="meta">'+safe(a.tag||'Just listed')+' · '+safe(a.category)+'</p></div></div>'+artCard(a)+'</div>').join('');return '<section class="section fill" style="padding-top:22px"><div class="shell"><div style="height:190px;border-radius:18px;'+(photos[0]&&photos[0].img?'background-image:url('+photos[0].img+');background-size:cover;background-position:center':'background:'+catBg(photos[0]?photos[0].category:'Digital Art'))+';border:1px solid #3B3F45"></div><div style="display:flex;gap:18px;align-items:flex-end;flex-wrap:wrap;padding:0 14px;margin-top:-52px"><div class="artist-avatar avatar-mono" style="width:118px;height:118px;font-size:56px;border:4px solid #111316;background:#24272A;overflow:hidden">'+avatarInner(example,name)+'</div><div style="flex:1;min-width:230px;padding-bottom:6px"><h1 class="page-title" style="font-size:42px">'+safe(name)+'</h1><p class="meta" style="margin-top:2px">'+safe(email)+' · '+(example?'Digital artist · Inner Circle':'Artist studio')+(handle?' · '+safe(handle):'')+(pr?' · '+safe(pr):'')+'</p><div style="margin-top:9px">'+ageBadge(example?AGES[name]:ageFromDob(acct.dob,new Date()),true)+'</div><div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap"><span class="badge">PAIRED MEMBER</span>'+(example?'<span class="badge" style="background:#FFC94D;color:#241203">#1 WORLD SERPENT</span>':'<span class="badge" style="background:#1d5c38;color:#b8ffd2">13+ VERIFIED ✦</span>')+'</div></div><div style="display:flex;gap:10px;padding-bottom:10px"><a class="primary" href="#/sell" style="text-decoration:none;padding:12px 18px;border-radius:12px">+ ADD ARTWORK</a><a class="outline" href="#/messages" style="text-decoration:none;padding:12px 18px;border-radius:12px">MESSAGES ✉</a>'+(example?'':'<button class="outline" data-action="logout" style="padding:12px 18px;border-radius:12px">LOG OUT</button>')+'</div></div><div style="display:flex;gap:6px;flex-wrap:wrap;border-top:1px solid #3B3F45;border-bottom:1px solid #3B3F45;padding:10px 6px;margin-top:8px"><button class="small-btn" data-action="scrollto" data-target="acct-feed">Listings</button><button class="small-btn" data-action="scrollto" data-target="acct-intro">About</button><button class="small-btn" data-action="scrollto" data-target="acct-orders">Orders</button><button class="small-btn" data-action="scrollto" data-target="acct-reviews">Reviews</button><span class="meta" style="margin-left:auto;align-self:center">'+plural(mine.length,'listing')+' · '+plural(example?3:0,'order')+' · '+plural(likes().length,'saved piece')+'</span></div>'+(example?'<p class="meta" style="margin-top:12px">Example account — this is what an artist’s profile looks like. Sign up on the Sell page and this page becomes yours. Already have an account on this device? <a class="text-link" href="#/login">LOG IN →</a></p>':'')+'<div class="two-col" style="margin-top:20px;align-items:start"><div>'+(example?'':'<div class="panel" style="margin-bottom:16px"><h3>EDIT YOUR PROFILE</h3><p class="sub" style="margin:8px 0 12px;font-size:13px">Your bio and profile picture pass an <b style="color:#fff">AI safety check</b> before they appear — nothing public goes up unscreened.</p><form id="profileForm"><label for="pfPic" style="display:block;font-size:12px;font-weight:900;margin-bottom:8px">PROFILE PICTURE</label><input id="pfPic" class="field" type="file" accept="image/*" style="margin-bottom:6px"><p class="form-note" style="margin-bottom:12px">JPG or PNG, up to 8 MB. Square pictures frame best.</p><label for="pfBio" style="display:block;font-size:12px;font-weight:900;margin-bottom:8px">YOUR BIO</label><textarea id="pfBio" class="field" maxlength="300" rows="3" placeholder="Tell the world who you are…">'+safe(get(STORE.profile,{}).bio||'')+'</textarea><p class="form-note" style="margin:6px 0 12px">Up to 300 characters. Keep contact details out of your bio — conversations stay here, where they\'re protected.</p><button class="primary" type="submit" style="width:100%">SAVE — RUN THE SAFETY CHECK</button><p id="pfMsg" style="margin-top:10px;line-height:1.6" role="alert"></p></form></div>')+'<div class="panel" id="acct-intro" style="margin-bottom:16px"><h3>Intro</h3>'+(example?'<p style="line-height:1.75;margin-top:8px;font-style:italic">“I paint impossible color and friendly monsters. Commissions are open — message me and let\'s make something loud.”</p>':(get(STORE.profile,{}).bio?'<p style="line-height:1.75;margin-top:8px;font-style:italic">“'+safe(get(STORE.profile,{}).bio)+'”</p>':''))+'<p style="line-height:1.9;margin-top:8px">✦ '+(example?'Digital artist painting impossible color':'Independent artist studio')+'<br>Location — '+(example?'Austin, Texas':'Online')+'<br>✦ Member of the Inner Circle'+(pr?'<br>Pronouns — '+safe(pr):'')+'<br>✦ Joined PAIRED 2026<br>🛡 Age band shown publicly — never a birthdate. Minor accounts get extra protections.</p></div><div class="panel" id="acct-reviews" style="margin-bottom:16px"><h3>Rating &amp; reviews</h3>'+(rating?'<div style="margin-top:8px">'+stars(rating.r)+' <b style="color:#fff">'+rating.r+'</b><p class="meta">'+rating.n+' customer reviews</p></div><p style="line-height:1.65;font-style:italic;margin-top:10px">“'+safe((REVIEWS['Nova Reyes']||[])[0].q)+'”</p><p class="meta">— Maya R. · Custom portrait</p>':'<p class="sub" style="margin-top:8px">No ratings yet — your first sale starts your climb to World Serpent.</p>')+'</div><div class="panel"><h3>Photos</h3><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px">'+photos.map(a=>'<div class="acct-photo" style="background:'+a.bg+'">'+(a.img?'<img src="'+a.img+'" alt="">':noImgArt(a))+'</div>').join('')+'</div></div></div><div><div id="acct-feed">'+(mine.length||example?posts:'<div class="panel" style="margin-bottom:16px"><p class="sub">No posts yet. Your stage is empty — for about five minutes.</p><div class="actions" style="margin-top:12px"><a class="primary" href="#/sell" style="text-decoration:none;padding:12px 18px;border-radius:12px">LIST YOUR FIRST MASTERPIECE ↗</a></div></div>')+'</div><div class="panel" id="acct-orders"><h3>Recent orders</h3>'+(example?'<p style="line-height:1.9;margin-top:8px">• <b style="color:#fff">Chromatic Serpent</b> — delivered ✦ Maya R. left a ★★★★★ review<br>• <b style="color:#fff">Custom portrait</b> — in the studio, ships Friday<br>• <b style="color:#fff">Neon Botanica (print)</b> — delivered ✦</p>':'<p class="sub" style="margin-top:8px">No orders yet. When a customer buys your art, it lands here — with delivery status and their review.</p>')+'</div><div class="panel" style="margin-top:16px"><h3>My membership</h3><p style="line-height:1.8;margin-top:8px"><b style="color:#fff">Paired</b> — ${TIER_DATA[1].price}/mo · ${TIER_DATA[1].fee}% per sale<br>Unlimited listings · commissions · analytics</p><div class="actions" style="margin-top:10px"><a class="outline" href="#/membership" style="text-decoration:none;padding:11px 16px;border-radius:12px">MANAGE MEMBERSHIP</a></div><p class="form-note" style="margin-top:10px">Example view — billing is not active in this preview.</p></div>'+rolePanelHtml+switchHtml+'</div></div></div></section>'}
/* FOUNDING 100 (queue 3, 2026-10-25) — recruitment machine: honest live counter,
   application intake (slither-founding-v1), mix targets, preview-artist wall,
   shareable artist profiles. No fabricated founders or counts, ever. */
function foundingApps(){return get(STORE.founding,[])}
function foundingSeatsClaimed(){/* PRODUCTION: this is the single swap point — the
  engine replaces this body with the real server cohort count; the page reads
  only this function. In the demo it counts real local applications, nothing else. */
  return foundingApps().length}
function foundingNorm(s){return String(s||'').trim().toLowerCase().replace(/^@+/,'')}
const FOUNDING_LOCK_SAVE=(TIER_DATA[1].monthly-FOUNDING_PRICE)*FOUNDING_MONTHS; /* $95.76 across the 24-month lock */
const MIX_LANES=[
 {key:'painters',label:'PAINTERS',target:40,blurb:'The anchors — originals that hold a wall and stop a scroll.',cats:['Painting']},
 {key:'illustrators',label:'ILLUSTRATORS & PRINT',target:35,blurb:'Feeds, fandoms, editions — the image-makers people collect in series.',cats:['Illustration','Drawing & Sketch','Printmaking','Prints & Posters','Anime & Manga Style','Character Design']},
 {key:'commissions',label:'COMMISSION ARTISTS',target:25,blurb:'The Board’s heartbeat — artists who make the thing that does not exist yet, for one person.',cats:['Commissions','Custom Portraits','Pet Portraits']}];
function mixLaneFor(cat){for(let l of MIX_LANES)if(l.cats.indexOf(cat)>=0)return l.key;return 'other'}
function submitFoundingApplication(d){
 let name=String(d.name||'').trim(),email=String(d.email||'').trim(),category=String(d.category||''),work=String(d.work||'').trim(),why=String(d.why||'').trim(),comm=String(d.commissions||'Yes — commissions open');
 if(name.length<2)return{ok:false,why:'fields',msg:'Tell us your artist name or username — founders are named, never numbered.'};
 if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email))return{ok:false,why:'fields',msg:'That email does not look complete — it is how the founding list reaches you at launch.'};
 if(CATEGORIES.indexOf(category)<0)return{ok:false,why:'fields',msg:'Pick the category closest to your primary craft.'};
 if(work.length<4)return{ok:false,why:'fields',msg:'Show us your work — a portfolio link, or a few lines about what you make.'};
 let bc=bioCheck(name+' '+why);
 if(!bc.ok)return{ok:false,why:bc.why,msg:bc.why==='contact'?'🛡 Contact details can’t ride in your name or why-line — your email stays private inside the application itself.':'🛡 Our safety check flagged words in your application, so it has not been stored. Try a kinder wording — the house stays welcoming.'};
 /* The work field may BE a portfolio link: bioCheck's contact verdict is expected
    there and allowed, because an application is private — it is never published.
    The language check still applies in full. */
 let wc=bioCheck(work);
 if(!wc.ok&&wc.why==='language')return{ok:false,why:'language',msg:'🛡 Our safety check flagged words in your work description, so it has not been stored. Try a kinder wording.'};
 if(!wc.ok&&wc.why==='contact'&&!/(https?:\/\/|www\.)[^\s]+/i.test(work))return{ok:false,why:'contact',msg:'🛡 Contact details can’t ride in your application text — a portfolio link is welcome, but emails and phone numbers stay out; the application itself carries your email privately.'};
 let apps=foundingApps(),nu=foundingNorm(name),ne=email.toLowerCase();
 if(apps.some(a=>foundingNorm(a.name)===nu||String(a.email||'').toLowerCase()===ne))return{ok:false,why:'dupe',msg:'This artist name or email already has a founding application on this device — one application per artist, and yours is already on the list here.'};
 let app={id:Date.now(),name:name,email:email,category:category,work:work,commissions:comm,why:why,lane:mixLaneFor(category),at:Date.now()};
 set(STORE.founding,[app,...apps]);addAlert('founding','✦ Founding 100 application received — '+app.name+' · '+app.category+'. That is seat '+foundingSeatsClaimed()+' of 100 claimed on this device.','#/founding100');
 return{ok:true,app:app}}

/* ADDICTION LOOP (queue 10, DOMINANCE-PLAN Beast Mode) — Fresh Today rail,
   Your Board, real alerts. House rails: every count on these surfaces traces
   to a stored record; no fake notifications, no invented "new" content. */
function dayIndex(){return Math.floor(Date.now()/864e5)}
function freshPieces(day){let items=all();if(!items.length)return[];let d=(day==null?dayIndex():day);let off=((d%items.length)+items.length)%items.length;let out=[];for(let i=0;i<Math.min(4,items.length);i++)out.push(items[(off+i)%items.length]);return out}
function spotlightNames(){return [...new Set(all().map(a=>a.artist))]}
function spotlightWeek(){return Math.floor(Date.now()/6048e5)}
function spotlightAt(weeksAgo){let names=spotlightNames();if(!names.length)return '';let ix=((spotlightWeek()-(weeksAgo||0))%names.length+names.length)%names.length;return names[ix]}
function spotlightArtist(){return spotlightAt(0)}
/* PHASE 3 — THE ADDICTION ENGINE (Daily Edit · Commission Match · Follows).
   Honesty law: every signal below is computed ONLY from stored records
   (slither-follows-v1, slither-likes-v1, slither-alerts-v1) plus the
   catalog itself. Nothing is invented: no scores, no percentages, no
   phantom activity. */
function follows(){let f=get(STORE.follows,[]);return Array.isArray(f)?f:[]}
function isFollowing(name){return follows().indexOf(name)>=0}
function toggleFollow(name){let f=follows();let on=f.indexOf(name)<0;set(STORE.follows,on?[...f,name]:f.filter(function(x){return x!==name}));return on}
function followBtn(name){let on=isFollowing(name);return '<button class="outline follow-btn'+(on?' following':'')+'" data-action="follow" data-artist="'+safe(name)+'" aria-pressed="'+(on?'true':'false')+'">'+(on?'✦ FOLLOWING':'✦ FOLLOW')+'</button>'}
function savedCategories(){let ids=likes();let counts={};all().forEach(function(a){if(ids.indexOf(a.id)>=0)counts[a.category]=(counts[a.category]||0)+1});return Object.keys(counts).sort(function(x,y){return counts[y]-counts[x]||(x<y?-1:1)})}
/* YOUR DAILY EDIT — a pure function of (day, stored signals, catalog):
   the deterministic daily rotation (freshPieces) reordered by real
   signals only — followed artists first (boost 2), saved categories
   next (boost 1), stable by rotation order inside a tier. Each boosted
   piece carries its honest why-label; unboosted pieces carry none. */
function dailyEdit(day){let base=freshPieces(day);let f=follows();let sc=savedCategories();let scored=base.map(function(a,i){let boost=0,why='';if(f.indexOf(a.artist)>=0){boost=2;why='Because you follow '+a.artist}else if(sc.indexOf(a.category)>=0){boost=1;why='More '+a.category+' — you save '+a.category.toLowerCase()+' work'}return{a:a,ix:i,boost:boost,why:why}});scored.sort(function(x,y){return y.boost-x.boost||x.ix-y.ix});return scored}
function artistCategories(name){let cats=[];all().forEach(function(a){if(a.artist===name&&cats.indexOf(a.category)<0)cats.push(a.category)});return cats}
/* COMMISSION MATCH — category overlap only. Order: the board's own
   standing (rating, then review count), then name. No match scores. */
function strongMatches(b){if(!b||!b.category)return[];let names=[...new Set(all().map(a=>a.artist))].filter(function(n){return n!==b.buyer&&artistCategories(n).indexOf(b.category)>=0});names.sort(function(x,y){let rx=RATINGS[x]?RATINGS[x].r:0,ry=RATINGS[y]?RATINGS[y].r:0;if(ry!==rx)return ry-rx;let nx=RATINGS[x]?RATINGS[x].n:0,ny=RATINGS[y]?RATINGS[y].n:0;if(ny!==nx)return ny-nx;return x<y?-1:1});return names.slice(0,3)}
/* FOLLOWED ARTIST RELEASES — pieces by followed artists inside today's
   daily rotation, and the real alerts they generate (once per day per
   artist, deduped by a stored fkey on the alert record itself). */
function followedReleases(day){let f=follows();if(!f.length)return[];return freshPieces(day).filter(function(a){return f.indexOf(a.artist)>=0})}
function noteFollowReleases(){let f=follows();if(!f.length)return;let day=dayIndex();let rel=followedReleases(day);if(!rel.length)return;let list=getAlerts();let changed=false;let seen={};rel.forEach(function(a){if(seen[a.artist])return;seen[a.artist]=1;let key='follow:'+day+':'+a.artist;if(list.some(function(x){return x.fkey===key}))return;list.push({id:Date.now()+list.length,type:'follow',fkey:key,text:'✦ New today from '+a.artist+': “'+a.title+'” is in today’s daily rotation — '+money(a.price)+'.',link:'#/art/'+a.id,at:Date.now(),read:false});changed=true});if(changed){if(list.length>60)list=list.slice(list.length-60);set(STORE.alerts,list)}}
function followStrip(){noteFollowReleases();let f=follows();let rel=followedReleases();
if(f.length&&rel.length){let tiles=rel.map(function(a){return '<a class="fresh-tile" href="#/art/'+a.id+'">'+(a.img?'<span class="fresh-art"><img src="'+safe(a.img)+'" alt="" loading="lazy"></span>':'<span class="fresh-art" style="background:'+safe(a.bg)+'">◉</span>')+'<span class="badge badge-new">✦ NEW TODAY</span><span class="fresh-k">'+safe(a.category)+'</span><b>'+safe(a.title)+'</b><span class="fresh-s">by '+safe(a.artist)+' · '+money(a.price)+'</span><span class="fresh-why">✦ Because you follow '+safe(a.artist)+'</span></a>'}).join('');return '<section class="section alt wash-rose"><div class="shell"><div class="section-top"><div><div class="eyebrow eb-rose">Followed artist releases</div><h2 class="section-title">NEW FROM ARTISTS <span class="paint">YOU FOLLOW.</span></h2><p class="sub">Pieces by artists you follow, inside today’s rotation — badged the day they land, and mirrored in your alerts. Real follows, real rotation; nothing scheduled, nothing invented.</p></div><a class="text-link" href="#/alerts">YOUR ALERTS →</a></div><div class="fresh-rail">'+tiles+'</div></div></section>'}
if(f.length){return '<section class="section"><div class="shell"><div class="panel"><div class="eyebrow">Followed artist releases</div><h3 style="font-size:24px;margin:8px 0 6px">NOTHING NEW FROM YOUR ARTISTS — TODAY.</h3><p class="sub" style="margin:6px 0 14px">You follow '+f.map(safe).join(', ')+'. When a piece by one of them rotates into the daily mix, it lands here badged NEW TODAY — with a real alert in your pulse.</p><a class="outline" href="#/artists" style="text-decoration:none;display:inline-flex;align-items:center;padding:12px 18px;border-radius:12px">MEET MORE ARTISTS →</a></div></div></section>'}
let ranked=[...new Set(all().map(a=>a.artist))].filter(function(n){return RATINGS[n]});ranked.sort(function(a,b){return RATINGS[b].r-RATINGS[a].r||RATINGS[b].n-RATINGS[a].n});let rows=ranked.slice(0,3).map(function(n){return '<div class="follow-row">'+avatarMono(n)+'<div style="flex:1;min-width:180px"><b style="color:#fff;font-size:17px">'+safe(n)+'</b><p class="meta">'+artistCategories(n).map(safe).join(' · ')+' · '+RATINGS[n].n+' customer reviews</p></div>'+followBtn(n)+'</div>'}).join('');return '<section class="section"><div class="shell"><div class="section-top"><div><div class="eyebrow eb-rose">Followed artist releases</div><h2 class="section-title">FOLLOW THE <span class="paint">HANDS.</span></h2><p class="sub">Follow an artist and their pieces surface here the day they rotate in — badged NEW TODAY, with a real alert in your pulse. Start with the board’s leaders:</p></div><a class="text-link" href="#/top">THE TOP SELLERS BOARD →</a></div><div class="panel">'+rows+'</div></div></section>'}
function freshToday(){let dateStr=new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'});let spot=spotlightArtist();let edit=dailyEdit();let hasSig=follows().length>0||likes().length>0;let tiles='';tiles+='<a class="fresh-tile" href="#/spotlight"><span class="fresh-k">✦ This week’s spotlight</span><b>'+safe(spot)+'</b><span class="fresh-s">@'+safe(USERNAMES[spot]||'')+' · on the stage right now</span></a>';allBriefs().slice(0,2).forEach(function(b){tiles+='<a class="fresh-tile" href="#/board"><span class="fresh-k">✉ New on the board</span><b>'+safe(b.title)+'</b><span class="fresh-s">'+safe(b.category)+' · Budget '+money(b.budget)+'</span></a>'});edit.forEach(function(e){let a=e.a;tiles+='<a class="fresh-tile" href="#/art/'+a.id+'">'+(a.img?'<span class="fresh-art"><img src="'+safe(a.img)+'" alt="" loading="lazy"></span>':'<span class="fresh-art" style="background:'+safe(a.bg)+'">◉</span>')+'<span class="fresh-k">'+safe(a.category)+'</span><b>'+safe(a.title)+'</b><span class="fresh-s">by '+safe(a.artist)+' · '+money(a.price)+'</span>'+(e.why?'<span class="fresh-why">✦ '+safe(e.why)+'</span>':'')+'</a>'});tiles+='<a class="fresh-tile" href="#/founding100"><span class="fresh-k">✦ Founding 100</span><b>'+foundingSeatsClaimed()+' of 100 seats claimed</b><span class="fresh-s">Real applications stored on this device — the counter never invents a founder.</span></a>';let ttl=hasSig?'YOUR DAILY <span class="paint">EDIT.</span>':'THE DAILY <span class="paint">MIX.</span>';let sub=hasSig?'Tuned by what you actually do here — artists you follow first, categories you save boosted, every label traced to a real signal. Rotates daily; nothing here is invented.':'A new mix every morning — the week’s spotlight, the newest briefs, pieces on a daily rotation, and the founding counter. Rotates daily; nothing here is invented. Follow artists and save pieces, and this board becomes your Daily Edit — tuned to you.';return '<section class="section fresh-sec wash-teal"><div class="shell"><div class="section-top"><div><div class="eyebrow eb-teal">FRESH TODAY — '+safe(dateStr.toUpperCase())+'</div><h2 class="section-title">'+ttl+'</h2><p class="sub">'+sub+'</p></div><a class="text-link" href="#/board">OPEN THE BOARD →</a></div><div class="fresh-rail">'+tiles+'</div></div></section>'}

function memberCategories(){let su=get(STORE.signup,null);if(!su||!su.username)return[];let prof=get(STORE.profile,{});let pcats=Array.isArray(prof.categories)?prof.categories.filter(function(c){return CATEGORIES.indexOf(c)>=0}):[];if(pcats.length)return pcats;let lcats=[];get(STORE.listings,[]).forEach(function(l){if(l.category&&lcats.indexOf(l.category)<0)lcats.push(l.category)});if(lcats.length)return lcats;let fcats=[];let me=foundingNorm(su.username),em=low(su.email);foundingApps().forEach(function(a){if((me&&foundingNorm(a.name)===me)||(em&&low(a.email)===em)){if(a.category&&fcats.indexOf(a.category)<0)fcats.push(a.category)}});if(fcats.length)return fcats;let cn=Object.keys(USERNAMES).find(function(n){return USERNAMES[n]===low(su.username).replace(/^@+/,'')||low(n)===low(su.username)});return cn?artistCategories(cn):fcats}
function yourBoardStrip(){let su=get(STORE.signup,null);if(!su||!su.username)return '';let cats=memberCategories();if(!cats.length)return '<div class="panel your-board"><div class="eyebrow">Your board</div><h3 style="font-size:22px;margin:6px 0 4px">THIS WALL TUNES ITSELF TO YOU.</h3><p class="sub" style="margin:6px 0 14px">Tell us your categories and briefs in your world surface here, first. List a piece in your craft, or apply to the Founding 100 under your primary category, and this strip wakes up.</p><a class="outline" href="#/account" style="text-decoration:none;display:inline-flex;align-items:center;padding:12px 18px;border-radius:12px">GO TO YOUR PROFILE →</a></div>';let matched=allBriefs().filter(function(b){return cats.indexOf(b.category)>=0});if(!matched.length)return '<div class="panel your-board"><div class="eyebrow">Your board · '+cats.map(safe).join(' · ')+'</div><h3 style="font-size:22px;margin:6px 0 4px">NOTHING IN YOUR WORLD — YET.</h3><p class="sub" style="margin-top:6px">No open briefs in your categories on this device right now. The full wall is below — and the next brief in your world lands here first.</p></div>';return '<div class="your-board"><div class="section-top" style="margin-bottom:14px"><div><div class="eyebrow">Matched for you · Matches your categories</div><h3 style="font-size:24px;margin-top:6px">IN YOUR <span class="paint">WORLD.</span></h3></div><p class="meta" style="max-width:320px">Briefs in '+cats.map(safe).join(', ')+' — surfaced first for you. The full wall is right below, unchanged.</p></div><div class="brief-grid">'+matched.slice(0,4).map(function(b){return briefCard(b,true)}).join('')+'</div></div>'}
function getAlerts(){return get(STORE.alerts,[])}
function unreadAlerts(){return getAlerts().filter(function(a){return !a.read}).length}
function addAlert(type,text,link){let list=getAlerts();list.push({id:Date.now()+Math.floor(Math.random()*1000),type:type,text:text,link:link||'',at:Date.now(),read:false});if(list.length>60)list=list.slice(list.length-60);set(STORE.alerts,list);return list}
function markAlertsRead(){let list=getAlerts();if(list.some(function(a){return !a.read})){list.forEach(function(a){a.read=true});set(STORE.alerts,list)}}
