function noteProposalArrived(p,brief){addAlert('proposal','✦ Proposal arrived in your thread with '+p.contact+': “'+p.briefTitle+'” — '+money(proposalMath(p.items,p.offered,p.selected,p.mult,p.tier).total)+' total (demo).','#/messages');if(brief&&brief.mine)addAlert('pitch','✦ A pitch landed on your brief “'+brief.title+'” — a proposal is waiting in the thread.','#/messages')}
