function alertsPage(){let list=getAlerts().slice().sort(function(a,b){return b.at-a.at});markAlertsRead();let icons={pitch:'✦',proposal:'✦',brief:'✦',founding:'✦',drop:'✦',follow:'✦'};let rows=list.length?list.map(function(a){return '<div class="alert-row"><span class="alert-ic">'+(icons[a.type]||'✦')+'</span><div style="flex:1;min-width:0"><p style="line-height:1.6;margin:0">'+safe(a.text)+'</p><p class="meta" style="margin-top:4px">'+new Date(a.at).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+(a.link?' · <a class="text-link" href="'+safe(a.link)+'">OPEN →</a>':'')+'</p></div>'+(a.read?'':'<span class="badge" style="background:#1d5c38;color:#b8ffd2;flex:none">NEW</span>')+'</div>'}).join(''):'<div class="empty">No alerts yet — real moves land here. Pitch a brief, send a proposal, post a brief in your categories, or apply to the Founding 100.</div>';return '<div class="page-hero" style="--ph:#FF7AD9"><div class="shell"><div class="eyebrow">Your alerts</div><h1 class="page-title">THE <span class="paint">PULSE.</span></h1><p class="sub">Your activity on this device — every alert here traces to a stored event in this browser: a pitch, a proposal, a brief in your world, a Sound order or delivery, a new release from an artist you follow, your founding application, a drop reminder you set. Nothing scheduled, nothing invented, no “someone viewed you” fiction.</p></div></div><section class="section fill"><div class="shell" style="max-width:840px"><div class="panel">'+rows+'</div></div></section>'}
