function trackById(id){return TRACKS.find(function(t){return t.id===id})||null}
function musicianByName(name){return MUSICIANS.find(function(m){return m.name===name})||null}
function soundPiece(t){return SEED.find(function(a){return a.id===t.piece})||SEED[0]}
function soundHue(g){let w=SOUND_WORLDS.find(function(x){return x.name===g});return w?w.hue:'#39D0C4'}
function creatorTier(name){return CREATOR_TIERS[name]||'Solo'}
function creatorFee(name,amount){let tier=creatorTier(name);let rate=TIER_FEES[tier]!=null?TIER_FEES[tier]:8;let fee=Math.round(amount*rate)/100;return{tier:tier,rate:rate,fee:fee,keep:Math.round((amount-fee)*100)/100}}
function soundStore(){let s=get(STORE.sound,null);if(!s||typeof s!=='object')s={orders:[],briefs:[]};if(!Array.isArray(s.orders))s.orders=[];if(!Array.isArray(s.briefs))s.briefs=[];return s}
function saveSound(s){set(STORE.sound,s)}
function persistSoundBrief(b){let s=soundStore();let ix=s.briefs.findIndex(function(x){return String(x.id)===String(b.id)});if(ix>=0)s.briefs[ix]=b;else s.briefs=[b,...s.briefs];saveSound(s)}
