let soundTimer=null;
function soundFmt(s){s=Math.max(0,Math.floor(Number(s)||0));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}
function soundStopTimer(){if(soundTimer){clearInterval(soundTimer);soundTimer=null}}
function soundStartTimer(){soundStopTimer();soundTimer=setInterval(function(){if(!state.soundOn)return;let t=trackById(state.soundPlay);if(!t){soundStopTimer();return}state.soundT+=0.25;if(state.soundT>=(t.preview||30)){state.soundT=t.preview||30;state.soundOn=false;soundStopTimer();render();return}soundPaint()},250);if(soundTimer&&soundTimer.unref)soundTimer.unref()}
function soundPaint(){let t=trackById(state.soundPlay);if(!t||!document.querySelectorAll)return;let pct=Math.min(100,(state.soundT/(t.preview||30))*100);document.querySelectorAll('[data-prog]').forEach(function(el){if(el.dataset&&el.dataset.prog===t.id&&el.style)el.style.width=pct+'%'});document.querySelectorAll('[data-time]').forEach(function(el){if(el.dataset&&el.dataset.time===t.id)el.textContent=soundFmt(state.soundT)+' / '+soundFmt(t.preview||30)})}
function soundToggle(id){let t=trackById(id);if(!t)return;if(state.soundPlay===id&&state.soundOn){state.soundOn=false;soundStopTimer();render();return}if(state.soundPlay!==id)state.soundT=0;state.soundPlay=id;state.soundOn=true;soundStartTimer();render()}
function soundClosePlayer(){state.soundPlay=null;state.soundOn=false;state.soundT=0;soundStopTimer()}
function soundPlaying(t){return state.soundPlay===t.id&&state.soundOn}
function soundPlayBtn(t,big){let on=soundPlaying(t);return '<button class="'+(big?'primary':'mini-btn')+' sound-play-btn" data-action="sound-play" data-track="'+t.id+'" aria-label="'+(on?'Pause':'Play')+' the demo preview of '+safe(t.title)+'">'+(on?'❚❚ PAUSE':'▶ PLAY PREVIEW')+'</button>'}
