function soundMini(){let t=trackById(state.soundPlay);if(!t)return '';let p=soundPiece(t);let pct=Math.min(100,(state.soundT/(t.preview||30))*100);return '<div class="mini-player" id="miniPlayer" style="--mh:'+soundHue(t.genre)+'"><img class="mini-thumb" src="'+safe(p.img)+'" alt=""><div class="mini-info"><b>'+safe(t.title)+'</b><span>'+safe(t.musician)+' · '+safe(t.genre)+' · DEMO PREVIEW</span><div class="sound-prog mini-prog"><i data-prog="'+t.id+'" style="width:'+pct+'%"></i></div></div><span class="sound-time" data-time="'+t.id+'">'+soundFmt(state.soundT)+' / '+soundFmt(t.preview||30)+'</span><button class="mini-btn" data-action="sound-play" data-track="'+t.id+'" aria-label="'+(state.soundOn?'Pause':'Play')+' preview">'+(state.soundOn?'❚❚':'▶')+'</button><a class="mini-btn mini-scene" href="#/sound/track/'+t.id+'">SCENE ↗</a><button class="mini-btn mini-close" data-action="sound-close" aria-label="Close the preview player">✕</button></div>'}
function soundCard(t){let p=soundPiece(t);let hue=soundHue(t.genre);return '<article class="panel track-card" style="--mh:'+hue+'"><a href="#/sound/track/'+t.id+'" aria-label="Open the scene for '+safe(t.title)+'"><div class="track-art" style="background:'+catBg(p.category)+'"><img src="'+safe(p.img)+'" alt="'+safe(p.title)+' — the painting paired with '+safe(t.title)+'" loading="lazy"><span class="tag">✦ THE PAIR</span></div></a><div class="track-body"><div class="meta"><span style="color:'+hue+';font-weight:900;letter-spacing:1.2px">'+safe(t.genre.toUpperCase())+'</span> · '+soundFmt(t.preview)+' DEMO PREVIEW</div><h3>'+safe(t.title)+'</h3><p class="meta">Music by <b style="color:#fff">'+safe(t.musician)+'</b><br>Painting: <a class="text-link" href="#/art/'+p.id+'">'+safe(p.title)+'</a> by '+safe(p.artist)+'</p><div class="track-actions">'+soundPlayBtn(t,false)+'<a class="outline track-open" href="#/sound/track/'+t.id+'">OPEN THE SCENE ↗</a></div><p class="meta">Track from '+money(SOUND_PRICES.trackPersonal)+' · THE PAIR from '+money(SOUND_PRICES.pairPersonal)+' — DEMO prices</p></div></article>'}
