function soundTrack(id){let t=trackById(id);if(!t)return notFound();let p=soundPiece(t);let m=musicianByName(t.musician);let hue=soundHue(t.genre);let lic=state.soundLic||'PERSONAL';let others=TRACKS.filter(function(x){return x.id!==t.id}).slice(0,3);
let licOpt=function(key,name,desc,priceHtml){return '<button type="button" class="lic-opt'+(lic===key?' on':'')+'" data-action="sound-lic" data-lic="'+key+'" aria-pressed="'+(lic===key?'true':'false')+'"><b>'+name+'</b><span>'+desc+'</span>'+priceHtml+'</button>'};
let licenses='<div class="lic-opts">'
+licOpt('PERSONAL','PERSONAL','Private listening and download. Noncommercial — not for ads, business promotion or monetized content.','<em>Track '+money(SOUND_PRICES.trackPersonal)+' · Pair '+money(SOUND_PRICES.pairPersonal)+' — DEMO</em>')
+licOpt('COMMERCIAL','COMMERCIAL','Creators and business: podcasts, monetized content and promotion, within the limits agreed with the artist.','<em>Track '+money(SOUND_PRICES.trackCommercial)+' · Pair '+money(SOUND_PRICES.pairCommercial)+' — DEMO</em>')
+licOpt('SYNC','SYNC','Film, TV, games and audiovisual media. Quoted per production — territory, duration and exclusivity set the price.','<em>Custom quote — message the artist</em>')
+'</div>';
let buy='';
if(lic==='SYNC'){buy='<div class="panel"><h3>SYNC IS A CONVERSATION, NOT A CHECKBOX.</h3><p class="sub" style="margin:8px 0 14px">Synchronization means marrying this composition and this recording to moving images — it is priced per production, never bundled into a tier. Tell the musician about the project and get a real quote.</p><div class="actions"><button class="primary" data-action="sound-contact" data-artist="'+safe(t.musician)+'">MESSAGE FOR A CUSTOM QUOTE ✉</button></div><p class="form-note" style="margin-top:12px">'+SOUND_PAY_LINE+'</p></div>'}
else{let tp=lic==='COMMERCIAL'?SOUND_PRICES.trackCommercial:SOUND_PRICES.trackPersonal;let pp=lic==='COMMERCIAL'?SOUND_PRICES.pairCommercial:SOUND_PRICES.pairPersonal;let artAlloc=pp-tp;
buy='<div class="buy-grid"><div class="panel"><div class="eyebrow">The track · '+lic+'</div><h3 style="font-size:26px;margin:6px 0">'+money(tp)+' <span class="meta">DEMO price</span></h3>'+soundFeeLine(t.musician,tp)+'<div class="actions" style="margin-top:12px"><button class="primary" data-action="sound-buy" data-kind="track" data-track="'+t.id+'">BUY TRACK (DEMO) ↗</button></div></div><div class="panel" style="border-color:'+hue+'"><div class="eyebrow" style="color:'+hue+'">✦ THE PAIR · '+lic+'</div><h3 style="font-size:26px;margin:6px 0">'+money(pp)+' <span class="meta">DEMO price</span></h3><p class="meta">Music allocation '+money(tp)+' + artwork allocation '+money(artAlloc)+' — each creator is paid their own allocation at their own tier fee:</p>'+soundFeeLine(t.musician,tp)+soundFeeLine(p.artist,artAlloc)+'<div class="actions" style="margin-top:12px"><button class="primary" data-action="sound-buy" data-kind="pair" data-track="'+t.id+'">BUY THE PAIR (DEMO) ↗</button></div></div></div><p class="form-note" style="margin-top:12px">'+SOUND_PAY_LINE+'</p>'}
let rights='<div class="identity-panel"><div class="eyebrow" style="margin-bottom:12px">Rights on record</div><dl class="id-rows"><div class="id-row"><dt>COMPOSITION</dt><dd>'+safe(t.rights.composition)+'</dd></div><div class="id-row"><dt>MASTER</dt><dd>'+safe(t.rights.master)+'</dd></div><div class="id-row"><dt>ARTWORK</dt><dd>'+safe(t.rights.artwork)+'</dd></div></dl><p class="id-attest-note" style="margin-top:12px">A Pair is never sold without a documented rights record from BOTH creators — that is the house rule, not a footnote. Artwork rights, plainly: a Pair license covers displaying the painting with the licensed music and a personal download under Personal; commercial reproduction only under Commercial. Copyright stays with the creators — buying a Pair never transfers ownership of the song or the painting.</p></div>';
let decl=m?'<p class="id-attest">✦ “'+safe(m.decl)+'”</p><p class="id-attest-note">— the human-made declaration of '+safe(t.musician)+', recorded as given. AI-generated music is not sold on PAIRED; AI-assisted mastering and ordinary editing are tooling, disclosed here — never authorship.</p>':'';
return `<section class="section" style="padding-top:22px"><div class="shell"><p class="meta" style="margin-bottom:14px"><a class="text-link" href="#/sound">← THE SOUND TRAIL</a> · <span style="color:${hue};font-weight:900;letter-spacing:1.2px">${safe(t.genre.toUpperCase())}</span></p><div class="sound-stage" style="--mh:${hue};background:${catBg(p.category)}"><img src="${safe(p.img)}" alt="${safe(p.title)} by ${safe(p.artist)} — the painting paired with ${safe(t.title)}"><span class="tag">✦ THE PAIR — “${safe(p.title)}” by ${safe(p.artist)}</span></div><div class="sound-player panel" style="--mh:${hue}"><div class="eyebrow" style="color:${hue}">Now previewing · demo player</div><h1 style="font-size:clamp(30px,4.6vw,44px);line-height:1.05;margin:8px 0 4px">${safe(t.title)}</h1><p class="meta">Music by <b style="color:#fff">${safe(t.musician)}</b> · Painting by <b style="color:#fff">${safe(p.artist)}</b> · ${soundFmt(t.preview)} preview</p><p style="line-height:1.65;margin:10px 0 14px">${safe(t.about)}</p>${soundProgress(t)}<div class="actions" style="margin-top:12px">${soundPlayBtn(t,true)}<button class="outline" data-action="sound-contact" data-artist="${safe(t.musician)}">MESSAGE THE MUSICIAN ✉</button><button class="outline" data-action="contact" data-artist="${safe(p.artist)}">MESSAGE THE PAINTER ✉</button></div><p class="form-note" style="margin-top:12px">Demo preview — a timed visual player. No audio streams in this prototype, and nothing ever autoplays; the real preview arrives with the engine.</p></div><div class="sound-cols"><div class="panel"><div class="eyebrow">The musician</div><h3 style="margin:8px 0 4px">${safe(t.musician)}</h3><p class="meta">${safe(t.genre)} · ${safe(creatorTier(t.musician))} tier · ${TIER_FEES[creatorTier(t.musician)]}% platform fee</p>${decl}<div class="actions" style="margin-top:12px"><button class="outline" data-action="sound-contact" data-artist="${safe(t.musician)}">MESSAGE ✉</button></div></div><div class="panel"><div class="eyebrow">The painter</div><h3 style="margin:8px 0 4px"><a class="text-link" href="#/artist/${safe(USERNAMES[p.artist]||'')}">${safe(p.artist)}</a></h3><p class="meta">“${safe(p.title)}” · ${safe(p.category)} · ${safe(p.medium)}${kindChip(p)}</p><p style="line-height:1.65;margin-top:8px">${safe(p.description)}</p><div class="actions" style="margin-top:12px"><a class="outline" href="#/art/${p.id}" style="text-decoration:none;display:inline-flex;align-items:center">VIEW THE PAINTING ↗</a><button class="outline" data-action="contact" data-artist="${safe(p.artist)}">MESSAGE ✉</button></div></div></div>${rights}<div class="panel"><div class="eyebrow">Choose your license</div><h3 style="margin:8px 0 14px">THREE CHOICES. <span class="paint">NO MAZE.</span></h3>${licenses}</div>${buy}</div></section><section class="section alt"><div class="shell"><div class="section-top"><div><div class="eyebrow">Keep walking</div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">MORE OF THE <span class="paint">TRAIL.</span></h2></div><a class="text-link" href="#/sound">ALL OF SOUND →</a></div><div class="art-grid">${others.map(soundCard).join('')}</div></div></section>`}
function soundBuy(trackId,kind){let t=trackById(trackId);if(!t)return;let lic=state.soundLic==='COMMERCIAL'?'COMMERCIAL':'PERSONAL';let tp=lic==='COMMERCIAL'?SOUND_PRICES.trackCommercial:SOUND_PRICES.trackPersonal;let pp=lic==='COMMERCIAL'?SOUND_PRICES.pairCommercial:SOUND_PRICES.pairPersonal;let price=kind==='pair'?pp:tp;let musicAlloc=kind==='pair'?tp:price;let artAlloc=kind==='pair'?pp-tp:0;let p=soundPiece(t);let order={id:Date.now(),track:t.id,title:t.title,kind:kind,license:lic,price:price,musicAlloc:musicAlloc,artAlloc:artAlloc,musician:t.musician,painter:p.artist,musicFee:creatorFee(t.musician,musicAlloc),artFee:kind==='pair'?creatorFee(p.artist,artAlloc):null,milestones:kind==='pair'?{music:'PENDING',art:'PENDING'}:{music:'PENDING'},at:Date.now(),demo:true};let s=soundStore();s.orders=[order,...s.orders];saveSound(s);addAlert('sound','✦ Demo order placed: “'+t.title+'” ('+(kind==='pair'?'THE PAIR':'TRACK')+', '+lic+') — delivery milestones are live on your Sound orders page. No payment was taken.','#/sound/orders');toast('Demo order placed — no payment taken ✦');go('/sound/orders')}
function soundDeliver(id,side){let s=soundStore();let o=s.orders.find(function(x){return String(x.id)===String(id)});if(!o||!o.milestones||o.milestones[side]!=='PENDING')return;o.milestones[side]='DELIVERED';saveSound(s);render();toast((side==='art'?'Artwork':'Music')+' marked delivered ✦ (demo)')}
function soundOrderFromBrief(b){if(!b)return null;let s=soundStore();let existing=s.orders.find(function(o){return o.briefId!=null&&String(o.briefId)===String(b.id)});if(existing)return existing;let need=b.kind==='PAIR'?['MUSIC','ART']:['MUSIC'];let legs={};for(let li=0;li<need.length;li++){let leg=need[li],cand=null;(b.proposals||[]).forEach(function(pr){if(pr.leg===leg&&pr.status!=='DECLINED')cand=pr});if(!cand||cand.status!=='ACCEPTED')return null;legs[leg]=cand}let mTot=function(pr){return proposalMath(pr.items,pr.offered,pr.selected,pr.mult,pr.tier).total};let musicAlloc=mTot(legs.MUSIC),artAlloc=b.kind==='PAIR'?mTot(legs.ART):0;let order={id:Date.now(),briefId:b.id,track:null,title:b.title,kind:b.kind==='PAIR'?'pair':'track',license:'COMMISSION',price:Math.round((musicAlloc+artAlloc)*100)/100,musicAlloc:musicAlloc,artAlloc:artAlloc,musician:legs.MUSIC.artist,painter:b.kind==='PAIR'?legs.ART.artist:'',musicFee:creatorFee(legs.MUSIC.artist,musicAlloc),artFee:b.kind==='PAIR'?creatorFee(legs.ART.artist,artAlloc):null,milestones:b.kind==='PAIR'?{music:'PENDING',art:'PENDING'}:{music:'PENDING'},at:Date.now(),demo:true,source:'brief'};s.orders=[order,...s.orders];saveSound(s);addAlert('sound','✦ Sound commission ordered: “'+b.title+'” ('+(b.kind==='PAIR'?'THE PAIR':'SONG')+', '+money(order.price)+' demo total) — every leg has its own delivery milestone on your Sound orders page. No payment was taken.','#/sound/orders');return order}
function soundOrders(){let s=soundStore();let rows=s.orders.map(function(o){let t=trackById(o.track);let mile=function(side,label,who){if(!o.milestones||!(side in o.milestones))return '';let st=o.milestones[side];return '<div class="mile-row"><div style="flex:1;min-width:0"><b>'+label+'</b> <span class="meta">— '+safe(who)+'</span></div>'+(st==='DELIVERED'?'<span class="badge" style="background:#1d5c38;color:#b8ffd2">✦ DELIVERED</span>':'<span class="badge">◷ PENDING</span><button class="mini-btn" data-action="sound-deliver" data-id="'+o.id+'" data-side="'+side+'">MARK DELIVERED (DEMO)</button>')+'</div>'};
let done=o.milestones&&Object.keys(o.milestones).every(function(k){return o.milestones[k]==='DELIVERED'});
return '<div class="panel" style="margin-bottom:16px"><div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"><span class="badge badge-violet">DEMO ORDER</span><span class="chip">✦ '+(o.kind==='pair'?'THE PAIR':'TRACK')+'</span><span class="chip">'+safe(o.license)+'</span></div><h3 style="margin-top:10px">'+safe(o.title)+'</h3><p class="meta">Music by '+safe(o.musician)+(o.kind==='pair'?' · Painting by '+safe(o.painter):'')+' · Placed '+new Date(o.at).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+'</p><div class="prop-total" style="margin-top:12px"><span>TOTAL (DEMO)</span><b>'+money(o.price)+'</b></div>'+soundFeeLine(o.musician,o.musicAlloc)+(o.kind==='pair'?soundFeeLine(o.painter,o.artAlloc):'')+'<div style="margin-top:12px">'+mile('music','MUSIC DELIVERY',o.musician)+mile('art','ARTWORK DELIVERY',o.painter)+'</div>'+(done?'<p style="margin-top:10px;color:#7CFC9A"><b>✦ '+(o.kind==='pair'?'THE PAIR IS COMPLETE':'DELIVERED')+'</b> — every milestone landed (demo).</p>':'<p class="meta" style="margin-top:10px">Each creator delivers on their own milestone — one landing never fakes the other.</p>')+'</div>'}).join('');
return `<div class="page-hero" style="--ph:#39D0C4"><div class="shell"><div class="eyebrow">PAIRED Sound</div><h1 class="page-title">YOUR SOUND <span class="paint">ORDERS.</span></h1><p class="sub">Demo orders from this browser — no payment was taken and no license was granted. Delivery milestones show exactly how a real Pair lands: two creators, two deliveries.</p></div></div><section class="section"><div class="shell" style="max-width:840px">${s.orders.length?rows:'<div class="empty">No Sound orders yet. Walk the trail, open a scene, and buy a track — or THE PAIR. <a class="text-link" href="#/sound">TO THE TRAIL →</a></div>'}</div></section>`}
function soundPropCard(b,pr){let m=proposalMath(pr.items,pr.offered,pr.selected,pr.mult,pr.tier);let ordP=soundStore().orders.find(function(o){return o.briefId!=null&&String(o.briefId)===String(b.id)});let locked=pr.status!=='PROPOSED'&&pr.status!=='COUNTERED';let addonRow=function(kind,label,amt,note){if(!pr.offered[kind])return '';let on=!!pr.selected[kind];return '<div class="prop-addon"><div><b>'+label+'</b> <span class="meta">'+note+'</span></div><div class="prop-addon-r"><b>'+(amt?money(amt):'—')+'</b>'+(locked?'':'<button class="mini-btn" data-action="sound-prop-addon" data-brief="'+safe(b.id)+'" data-id="'+pr.id+'" data-kind="'+kind+'">'+(on?'✓ ADDED':'ADD +')+'</button>')+'</div></div>'};
return '<div class="proposal-card"><div class="prop-head"><b>✦ SOUND PROPOSAL — '+(pr.leg==='ART'?'ARTWORK':'MUSIC')+' LEG</b><span class="badge">'+safe(pr.status)+'</span></div>'+stageRail(pr)+'<p class="meta" style="margin:8px 0">Artist: <b style="color:#fff">'+safe(pr.artist)+'</b> · Demo proposal — no payment moves here.</p><div class="prop-items">'+pr.items.map(function(i){return '<div class="prop-item"><span>'+safe(i.label)+'</span><b>'+money(i.price)+'</b></div>'}).join('')+'<div class="prop-item subtotal"><span>Base</span><b>'+money(m.base)+'</b></div></div>'+addonRow('rush','✦ RUSH',m.rush,'+100% of base — jumps the queue')+addonRow('privacy','✦ PRIVACY',m.privacy,'+50% of base — never posted publicly')+addonRow('commercial','✦ COMMERCIAL USE',m.commercial,'×'+m.mult+' of base (license uplift shown)')+'<div class="prop-total"><span>'+(pr.leg==='ART'?'ARTWORK':'MUSIC')+' TOTAL</span><b>'+money(m.total)+'</b></div><p class="prop-fee">Platform fee '+m.rate+'% ('+safe(pr.tier)+'): '+money(m.fee)+' — artist keeps '+money(m.keep)+' '+FEE_LABEL+'</p><p class="meta">◷ Delivery estimate: '+pr.days+' days · ✦ Revisions: '+pr.revisions+' round'+(Number(pr.revisions)===1?'':'s')+(pr.revNote?' — '+safe(pr.revNote):'')+'</p>'+(locked?'<p class="meta">'+(ordP?'✓ Accepted — this leg lives in your Sound order; deliveries land on the orders page (demo).':'✓ Accepted — this leg is locked into the combined total (demo).')+'</p>':'<div class="actions" style="margin-top:10px"><button class="primary" data-action="sound-prop-accept" data-brief="'+safe(b.id)+'" data-id="'+pr.id+'">ACCEPT THIS LEG ✓</button><button class="outline" data-action="sound-contact" data-artist="'+safe(pr.artist)+'">MESSAGE ✉</button></div>')+'</div>'}
function soundBriefCard(b){let props=(b.proposals||[]);let comb=soundCombined(b);let ordB=soundStore().orders.find(function(o){return o.briefId!=null&&String(o.briefId)===String(b.id)});let orderRow=ordB?'<div class="actions" style="margin-top:12px"><a class="primary" href="#/sound/orders" style="text-decoration:none;display:inline-flex;align-items:center">VIEW ORDER →</a><span class="meta">This brief is a live demo order now — each leg delivers on its own milestone.</span></div>':'';let match=MUSICIANS.filter(function(mn){return mn.genre===b.genre});let matchRow=match.length?'<div class="match-row"><span class="match-k">✦ MAKERS IN '+safe(b.genre).toUpperCase()+'</span><div class="match-list">'+match.map(function(mn){return '<span class="match-chip"><span class="match-mono">'+safe(monogram(mn.name))+'</span><b>'+safe(mn.name)+'</b><button class="mini-btn" data-action="sound-contact" data-artist="'+safe(mn.name)+'">MESSAGE ✉</button></span>'}).join('')+'</div></div>':'';
let combined=props.length?'<div class="prop-total" style="margin-top:12px"><span>'+(b.kind==='PAIR'?'COMBINED TOTAL (DEMO)':'TOTAL (DEMO)')+'</span><b>'+money(comb.total)+'</b></div>'+(b.kind==='PAIR'?'<p class="meta">Music '+money(comb.music)+(comb.hasArt?'':' (no artwork proposal yet)')+' + Artwork '+money(comb.art)+(comb.hasMusic?'':' (no music proposal yet)')+' — each creator is paid their own allocation at their own tier fee when the engine opens. Demo: no payment moves.</p>':'<p class="meta">The musician’s itemized total for this brief. Demo: no payment moves.</p>'):'';
return '<article class="panel brief-card"><div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"><span class="chip" style="color:'+soundHue(b.genre)+'">✦ '+safe(b.genre)+'</span><span class="badge badge-violet">'+(b.kind==='PAIR'?'✦ THE PAIR BRIEF':'SONG BRIEF')+'</span>'+(b.mine?'<span class="badge" style="background:#1d5c38;color:#b8ffd2">✦ YOUR BRIEF</span>':'<span class="badge">EXAMPLE BRIEF</span>')+'</div><h3>'+safe(b.title)+'</h3><div class="brief-meta"><span class="chip">Budget '+money(b.budget)+'</span><span class="chip">◷ '+safe(b.timeline)+'</span></div><p class="brief-details">'+safe(b.details)+'</p>'+matchRow+props.map(function(pr){return soundPropCard(b,pr)}).join('')+combined+orderRow+'<div class="brief-foot"><div class="brief-buyer"><div class="brief-avatar">'+safe((b.buyer||'C').charAt(0))+'</div><div><b style="color:#fff">'+safe(b.buyer)+'</b><p class="meta">Collector · '+(b.pitches||0)+' pitch'+((b.pitches||0)===1?'':'es')+' so far</p></div></div><span class="meta">Proposals land below the brief — itemized, per creator</span></div></article>'}
function soundBoard(){let briefs=allSoundBriefs();let kind=state.soundBriefKind||'PAIR';let cards=briefs.map(soundBriefCard).join('');
return `<div class="page-hero" style="--ph:#8B7CFF"><div class="shell"><div class="eyebrow">The Sound Board</div><h1 class="page-title">GET A SONG <span class="paint">MADE FOR YOU.</span></h1><p class="sub">Post the moment. Musicians pitch it — and for a PAIR brief, a painter proposes the artwork separately. You see every itemized line and the combined total before anyone accepts. Talk in the thread; close on the board.</p><div class="actions"><button class="primary" data-action="scrollto" data-target="post-sound-brief">POST A SOUND BRIEF ↗</button><a class="outline" href="#/sound" style="text-decoration:none;display:inline-flex;align-items:center">WALK THE TRAIL →</a></div></div></div><section class="section"><div class="shell"><div class="section-top"><div><div class="eyebrow">Open sound briefs</div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">THE SOUND <span class="paint">WALL.</span></h2></div><p class="meta" style="max-width:340px">Example briefs show how the board works — the wedding Pair below carries a live dual proposal. Briefs you post live here, in this browser.</p></div><div class="brief-grid">${cards}</div></div></section><section class="section alt" id="post-sound-brief"><div class="shell two-col"><div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">POST A <span class="paint">BRIEF.</span></h2><p class="sub" style="margin-bottom:16px">A song for a moment that matters — or the full Pair, song and painting from one brief.</p><div class="panel"><form id="soundBriefForm" class="form-grid"><div class="form-group full"><label>BRIEF TYPE *</label><div class="brief-types"><label class="type-card"><input type="radio" name="sbKind" value="SONG"${kind==='SONG'?' checked':''}> <b>SONG</b><span>An original song, made for you — one musician, one itemized proposal.</span></label><label class="type-card"><input type="radio" name="sbKind" value="PAIR"${kind==='PAIR'?' checked':''}> <b>THE PAIR</b><span>A song + an original painting. Two makers, two proposals, one combined total.</span></label></div></div><div class="form-group full"><label for="sbTitle">WHAT DO YOU WANT MADE? *</label><input id="sbTitle" class="field" name="title" placeholder="e.g. A song for my parents’ 40th — and the portrait to hang beside it" required maxlength="110"></div><div class="form-group"><label for="sbGenre">GENRE WORLD *</label><select id="sbGenre" class="field" name="genre">${SOUND_WORLDS.map(function(w){return '<option>'+safe(w.name)+'</option>'}).join('')}</select></div><div class="form-group"><label for="sbBudget">BUDGET (USD) *</label><input id="sbBudget" class="field" name="budget" type="number" min="1" max="100000" step="1" placeholder="500" required></div><div class="form-group full"><label for="sbTimeline">TIMELINE *</label><select id="sbTimeline" class="field" name="timeline"><option>This week</option><option>Within a month</option><option>1–3 months</option><option>No rush — when it is right</option></select></div><div class="form-group full"><label for="sbDetails">THE DETAILS *</label><textarea id="sbDetails" class="field" name="details" placeholder="The moment, the people, the feeling — anything that helps a maker hear it." required maxlength="700"></textarea></div><div class="full"><button class="primary" type="submit">POST MY SOUND BRIEF ✦</button><p id="soundBriefMsg" style="margin-top:10px;line-height:1.6" role="alert"></p><p class="form-note">Demo board — briefs are stored in this browser only. Keep contact details out of the brief; conversations stay here.</p></div></form></div></div><aside><div class="panel"><h3 style="margin-bottom:6px">✦ ANSWER A BRIEF — BUILD A PROPOSAL</h3><p class="meta" style="margin-bottom:14px">Makers: pick the brief, pick your leg, itemize your lines. Your tier fee is calculated from your own tier — shown before anyone accepts.</p><form id="soundPropForm" class="form-grid"><div class="form-group full"><label for="spBrief">FOR WHICH BRIEF?</label><select id="spBrief" class="field">${briefs.map(function(b){return '<option value="'+safe(b.id)+'">'+safe(b.title)+' ('+(b.kind==='PAIR'?'PAIR':'SONG')+')</option>'}).join('')}</select></div><div class="form-group"><label for="spLeg">YOUR LEG</label><select id="spLeg" class="field"><option value="MUSIC">Music — the song</option><option value="ART">Artwork — the painting (Pair briefs)</option></select></div><div class="form-group"><label for="spArtist">ARTIST NAME</label><input id="spArtist" class="field" maxlength="70" placeholder="The maker making this offer"></div><div class="form-group"><label>LINE ITEM 1</label><input class="field" data-slabel placeholder="e.g. Original song — full production" maxlength="90"></div><div class="form-group"><label>PRICE (USD)</label><input class="field" data-sprice type="number" min="1" max="100000" step="0.01" placeholder="300"></div><div class="form-group"><label>LINE ITEM 2</label><input class="field" data-slabel placeholder="e.g. Acoustic version" maxlength="90"></div><div class="form-group"><label>PRICE (USD)</label><input class="field" data-sprice type="number" min="1" max="100000" step="0.01" placeholder="100"></div><div class="form-group"><label for="spDays">DELIVERY ESTIMATE (DAYS)</label><input id="spDays" class="field" type="number" min="1" max="365" value="21"></div><div class="form-group"><label for="spRevisions">REVISION ROUNDS INCLUDED</label><input id="spRevisions" class="field" type="number" min="0" max="20" value="2"></div><div class="form-group full"><label>STANDARD ADD-ONS TO OFFER</label><div class="prop-offers"><label><input type="checkbox" id="spRush"> ✦ Rush (+100% of base)</label><label><input type="checkbox" id="spPrivacy"> ✦ Privacy (+50% of base)</label><label><input type="checkbox" id="spCommercial"> ✦ Commercial use (×2–3 of base)</label></div></div><div class="form-group"><label for="spMult">COMMERCIAL MULTIPLIER</label><select id="spMult" class="field"><option>2</option><option selected>2.5</option><option>3</option></select></div><div class="full"><button class="primary" type="submit">SEND PROPOSAL ✦</button><p id="soundPropMsg" style="margin-top:10px;line-height:1.6" role="alert"></p><p class="form-note">Demo builder — proposals live in this browser only, on the brief itself.</p></div></form></div><div class="steps" style="display:block;margin-top:20px"><div class="step"><span class="number">01</span><h3>ONE BRIEF</h3><p>Song or Pair — the moment, the budget, the deadline.</p></div><div class="step" style="margin-top:14px"><span class="number">02</span><h3>TWO PROPOSALS</h3><p>Music and artwork are proposed separately, itemized line by line, add-ons in the open.</p></div><div class="step" style="margin-top:14px"><span class="number">03</span><h3>ONE COMBINED YES</h3><p>Accept each leg when it is right. The combined total is the price — each creator keeps their own allocation, minus only their own tier fee.</p></div></div></aside></div></section>`}
