function previewStrip(){return `<div class="preview-strip"><b>PREVIEW</b><span>PAIRED is being built in the open. Browsing, saving, the Commission Board and the lists on this page work today, on this device. Payments, purchases and payouts are not yet active — they switch on with the production launch, and nothing here pretends otherwise.</span></div>`}
const LADDER_BANDS=[
 {name:'First Original',lo:175,hi:249,line:'The first original on your wall — a real one-of-one at a first-collector price.'},
 {name:'Everyday Statement',lo:250,hi:399,line:'The piece a room gets built around — originals with presence.'},
 {name:'Signature Piece',lo:400,hi:Infinity,line:'The anchor works: the boldest originals in the house.'}];
function ladderHTML(){let orig=all().filter(a=>identityOf(a).kind==='ORIGINAL');let maxOrig=orig.reduce((m,a)=>Math.max(m,a.price),0);let bands=LADDER_BANDS.map(b=>({b:b,pieces:orig.filter(a=>a.price>=b.lo&&a.price<=b.hi).sort((x,y)=>x.price-y.price)})).filter(x=>x.pieces.length);return `<div class="ladder-grid">${bands.map(x=>`<div class="panel band-card"><div class="eyebrow">${safe(x.b.name)}</div><div class="band-span">${money(x.b.lo)} – ${money(x.b.hi===Infinity?maxOrig:x.b.hi)}</div><p class="sub" style="margin-bottom:8px">${x.b.line}</p><p class="meta" style="margin-bottom:6px">${plural(x.pieces.length,'original')} on this rung</p>${x.pieces.map(a=>`<a class="band-row" href="#/art/${a.id}"><span class="band-title">${safe(a.title)}</span><span class="band-who">${safe(a.artist)}</span><b>${money(a.price)}</b></a>`).join('')}</div>`).join('')}</div>`}
function buyersPage(){let pieces=all();let prices=pieces.map(a=>a.price);let lo=prices.length?Math.min.apply(null,prices):0,hi=prices.length?Math.max.apply(null,prices):0;return `<section class="hero lp-hero"><div class="shell"><div class="lp-pair"><div class="hero-copy lp-copy"><div class="eyebrow">✦ For collectors · Buy art</div><h1>ART WORTH KNOWING <span class="paint">THE ARTIST</span> FOR.</h1><p class="hero-sub">Original, human-made art — and the person who made it, one tap from every frame. Every price printed in the open: the wall runs ${money(lo)} to ${money(hi)} today, and nothing hides behind a message.</p><div class="actions" style="margin-top:18px"><a class="primary cta-acid" href="#/explore" style="text-decoration:none;display:inline-flex;align-items:center">EXPLORE ART ↗</a><a class="primary" href="#/board" style="text-decoration:none;display:inline-flex;align-items:center">START A COMMISSION BRIEF ↗</a><button class="outline" data-action="scrollto" data-target="buyersJoin">JOIN THE BUYER LIST ↓</button><button class="outline" data-action="join-role" data-role="collector">CREATE A COLLECTOR ACCOUNT →</button></div><div class="proof" style="margin-top:22px"><span><b>✦</b> HUMAN-MADE ONLY</span><span><b>◉</b> ARTIST ON EVERY FRAME</span><span><b>∞</b> PRICES IN THE OPEN</span></div></div><div class="lp-frames"><div class="lp-frame lp-frame-art">${heroSpotlight()}</div>${pairSeam('MEETS')}<div class="lp-frame lp-frame-who">${heroArtistFrame()}</div></div></div></div></section>
<section class="section" style="padding-top:34px"><div class="shell">${previewStrip()}<div class="section-top"><div><div class="eyebrow eb-violet">The wall, today</div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">THE COLLECTION, <span class="paint">IN THE OPEN.</span></h2><p class="sub">This is the preview catalog — real pieces by named artists, shown exactly as the marketplace will open. Purchasing is not live yet; saving, following and briefs are. Every card carries its artist, its medium and its kind.</p></div><a class="text-link" href="#/explore">OPEN THE FULL WALL ↗</a></div><div class="art-grid">${pieces.map(artCard).join('')}</div></div></section>
<section class="section alt"><div class="shell"><div class="section-top"><div><div class="eyebrow eb-amber">Find your price point</div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">THREE RUNGS. <span class="paint">ALL ORIGINALS.</span></h2><p class="sub">The ladder is built from the originals actually on the wall — no invented stock, no borrowed price points. Artist-made prints start lower still: Golden Hour by Sam Rivera is ${money(175)} in the catalog above, and Otherworld by Jules Carter is ${money(190)}.</p></div></div>${ladderHTML()}<p class="meta" style="margin-top:14px">Bands are merchandising rungs over today's catalog; a rung only appears while a real original stands on it.</p></div></section>
<section class="section"><div class="shell"><div class="section-top"><div><div class="eyebrow">How buying will work</div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">FROM WALL <span class="paint">TO YOUR WALL.</span></h2><p class="sub">The full path, as it will run when purchasing opens — stated now so there are no surprises later.</p></div></div><div class="bs-steps4"><div class="step"><span class="number">01</span><h3>DISCOVER IT</h3><p>Find the piece in the open — every price printed, every artist named, every listing carrying its identity record: medium, dimensions, year, condition.</p></div><div class="step"><span class="number">02</span><h3>MEET THE ARTIST</h3><p>The frame always has a person attached. Message the artist, ask anything, follow their next drop — the conversation starts before any money exists.</p></div><div class="step"><span class="number">03</span><h3>PURCHASE OR COMMISSION <em class="launch-tag">Opens at launch</em></h3><p>Checkout will run piece by piece with the terms printed before money moves — or start from a brief and commission the piece that does not exist yet.</p></div><div class="step"><span class="number">04</span><h3>TRACK IT HOME <em class="launch-tag">Planned</em></h3><p>Artists pack and ship their own work. PAIRED provides shipment tracking and support along the way, until the piece is on your wall.</p></div></div></div></section>
<section class="section alt"><div class="shell"><div class="section-top"><div><div class="eyebrow eb-teal">The Paired Standard</div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">REAL ART. REAL PEOPLE. <span class="paint">CLEAR EXPECTATIONS.</span></h2><p class="sub">PAIRED is being built around original, human-made art and direct relationships with independent creators. These are the standards the house is built to — printed while they are being built, not after.</p></div></div><div class="steps"><div class="step"><span class="number">✦</span><h3>HUMAN-MADE ONLY</h3><p>Every piece here is made by a person's hands. No AI-generated work is sold on PAIRED — that is a rule of the house, not a filter you have to remember to set.</p></div><div class="step"><span class="number">✦</span><h3>ARTISTS REVIEWED BEFORE ADMISSION</h3><p>Artist applications are reviewed before anyone is admitted. The wall stays small on purpose — curation is what makes a collector's trust possible.</p></div><div class="step"><span class="number">✦</span><h3>THE ARTIST'S OWN DECLARATION</h3><p>Every listing carries the maker's signed human-made declaration and identity record — recorded as given, in the artist's own words, next to the work. Ask the artist anything in the thread; that is what it is for.</p></div><div class="step"><span class="number">✦</span><h3>EVERYTHING PRINTED</h3><p>Price, medium, dimensions, condition, shipping note, returns note — printed on the listing before any conversation starts. Nothing on this wall is “DM for price.”</p></div><div class="step"><span class="number">✦</span><h3>ARTISTS SHIP · PAIRED TRACKS <em class="launch-tag">Planned</em></h3><p>The artist packs and ships their own work — it never leaves the maker's hands for a warehouse. Order and shipment tracking is planned into the buying path from the start.</p></div><div class="step"><span class="number">✦</span><h3>TERMS BEFORE MONEY <em class="launch-tag">Planned</em></h3><p>Our return and dispute terms are published on the policy page — posted before checkout opens, and linked from the footer and every listing's buy area. This house does not advertise a protection that does not exist yet.</p></div></div><div class="actions" style="margin-top:18px"><a class="outline" href="#/policy" style="text-decoration:none;display:inline-flex;align-items:center;padding:13px 20px;border-radius:12px">READ THE PAIRED POLICY →</a></div><div class="notice" style="margin-top:22px">The honest state of the house: PAIRED is currently in preview. Payments, purchases, fulfillment and purchase-protection services are not yet active. Browsing, saving, the Commission Board and the early-access lists are live today.</div></div></section>
<section class="section" id="buyersJoin"><div class="shell two-col" style="align-items:start"><div><div class="eyebrow eb-amber">Buyer early access</div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">FIND YOUR <span class="paint">NEXT ORIGINAL.</span></h2><p class="sub" style="margin-bottom:18px">Join the buyer list and hear first when purchasing and commissioning open — early collectors walk in before the public line forms.</p>${doorCard('buyer')}</div><aside><div class="panel" style="border:2px solid var(--gold)"><div class="eyebrow" style="color:#ffd76a">✦ Or start from a blank wall</div><h3 style="margin-bottom:8px">THE PIECE YOU WANT MAY NOT EXIST YET.</h3><p class="sub" style="margin-bottom:14px">Post a brief on the Commission Board: artists pitch you their idea, their price and their timeline, and the thread becomes the commission. One brief — proposals, milestones, tracked delivery. Your next commission deserves more than a DM.</p><a class="primary" href="#/board" style="text-decoration:none;display:inline-flex;align-items:center">START A COMMISSION BRIEF ↗</a><p class="meta" style="margin-top:12px">Briefs you post today live on this device in the prototype — the Board opens to the Founding 100 at launch.</p></div></aside></div></section>`}
